package app

import (
	"os"
	"path/filepath"
	"runtime"

	"gopkg.in/yaml.v3"
)

type StyleRow struct {
	TextColor       string `yaml:"text-color,omitempty"`
	BackgroundColor string `yaml:"background-color,omitempty"`
	NumberColor     string `yaml:"number-color,omitempty"`
	DirectoryColor  string `yaml:"directory-color,omitempty"`
}

// The fields above are not used directly; concrete row types below preserve
// the exact YAML field ordering needed for each style section.

type FooterStyle struct {
	TextColor       string `yaml:"text-color"`
	BackgroundColor string `yaml:"background-color"`
	NumberColor     string `yaml:"number-color"`
}

type SelectedRowStyle struct {
	TextColor       string `yaml:"text-color"`
	BackgroundColor string `yaml:"background-color"`
}

type ResultRowStyle struct {
	NumberColor    string `yaml:"number-color"`
	DirectoryColor string `yaml:"directory-color"`
}

type HeaderStyle struct {
	TextColor       string `yaml:"text-color"`
	BackgroundColor string `yaml:"background-color"`
	Hidden          bool   `yaml:"hidden"`
}

type ProgressModalStyle struct {
	CurrentItemNameMaxLen int `yaml:"current-item-path-max-len"`
}

type Style struct {
	Footer        FooterStyle        `yaml:"footer"`
	SelectedRow   SelectedRowStyle   `yaml:"selected-row"`
	ResultRow     ResultRowStyle     `yaml:"result-row"`
	Header        HeaderStyle        `yaml:"header"`
	ProgressModal ProgressModalStyle `yaml:"progress-modal"`
	UseOldSizeBar bool               `yaml:"use-old-size-bar"`
}

type Sorting struct {
	By    string `yaml:"by"`
	Order string `yaml:"order"`
}

type Flags struct {
	Style              Style    `yaml:"style"`
	Sorting            Sorting  `yaml:"sorting"`
	CfgFile            string   `yaml:"-"`
	LogFile            string   `yaml:"log-file"`
	InputFile          string   `yaml:"input-file"`
	OutputFile         string   `yaml:"output-file"`
	IgnoreFromFile     string   `yaml:"ignore-from-file"`
	IgnoreDirs         []string `yaml:"ignore-dirs"`
	IgnoreDirPatterns  []string `yaml:"ignore-dir-patterns"`
	TypeFilter         []string `yaml:"type"`
	ExcludeTypeFilter  []string `yaml:"exclude-type"`
	MaxCores           int      `yaml:"max-cores"`
	Top                int      `yaml:"top"`
	Depth              int      `yaml:"depth"`
	SequentialScanning bool     `yaml:"sequential-scanning"`
	ShowDisks          bool     `yaml:"-"`
	ShowApparentSize   bool     `yaml:"show-apparent-size"`
	ShowRelativeSize   bool     `yaml:"show-relative-size"`
	ShowAnnexedSize    bool     `yaml:"show-annexed-size"`
	ShowVersion        bool     `yaml:"-"`
	ShowItemCount      bool     `yaml:"show-item-count"`
	ShowMTime          bool     `yaml:"show-mtime"`
	NoColor            bool     `yaml:"no-color"`
	Mouse              bool     `yaml:"mouse"`
	NonInteractive     bool     `yaml:"non-interactive"`
	NoProgress         bool     `yaml:"no-progress"`
	NoUnicode          bool     `yaml:"no-unicode"`
	NoCross            bool     `yaml:"no-cross"`
	NoHidden           bool     `yaml:"no-hidden"`
	NoDelete           bool     `yaml:"no-delete"`
	NoSpawnShell       bool     `yaml:"no-spawn-shell"`
	FollowSymlinks     bool     `yaml:"follow-symlinks"`
	Profiling          bool     `yaml:"profiling"`
	ReadFromStorage    bool     `yaml:"read-from-storage"`
	DbPath             string   `yaml:"db"`
	Summarize          bool     `yaml:"summarize"`
	UseSIPrefix        bool     `yaml:"use-si-prefix"`
	NoPrefix           bool     `yaml:"no-prefix"`
	ShowInKiB          bool     `yaml:"show-in-kib"`
	WriteConfig        bool     `yaml:"-"`
	ReverseSort        bool     `yaml:"reverse-sort"`
	ChangeCwd          bool     `yaml:"change-cwd"`
	DeleteInBackground bool     `yaml:"delete-in-background"`
	DeleteInParallel   bool     `yaml:"delete-in-parallel"`
	Since              string   `yaml:"since"`
	Until              string   `yaml:"until"`
	MaxAge             string   `yaml:"max-age"`
	MinAge             string   `yaml:"min-age"`
	ArchiveBrowsing    bool     `yaml:"archive-browsing"`
	CollapsePath       bool     `yaml:"collapse-path"`
}

func defaultFlags() Flags {
	return Flags{
		Style: Style{
			Footer: FooterStyle{
				TextColor:       "#000000",
				BackgroundColor: "#2479D0",
				NumberColor:     "#FFFFFF",
			},
			SelectedRow: SelectedRowStyle{},
			ResultRow: ResultRowStyle{
				NumberColor:    "#e67100",
				DirectoryColor: "#3498db",
			},
			Header: HeaderStyle{
				TextColor:       "#000000",
				BackgroundColor: "#2479D0",
			},
		},
		LogFile:           "/dev/null",
		IgnoreDirs:        []string{"/proc", "/dev", "/sys", "/run"},
		IgnoreDirPatterns: []string{},
		TypeFilter:        []string{},
		ExcludeTypeFilter: []string{},
		MaxCores:          runtime.NumCPU(),
	}
}

func resolveCfgFile(explicit string) string {
	if explicit != "" {
		return explicit
	}
	home, err := os.UserHomeDir()
	if err != nil || home == "" {
		return ""
	}
	preferred := filepath.Join(home, ".config", "gdu", "gdu.yaml")
	if _, err := os.Stat(preferred); err == nil {
		return preferred
	}
	return filepath.Join(home, ".gdu.yaml")
}

func loadConfig(flags *Flags) error {
	data, err := os.ReadFile(flags.CfgFile)
	if err != nil {
		return err
	}
	if err := yaml.Unmarshal(data, flags); err != nil {
		return err
	}
	return nil
}

func writeConfigFile(flags *Flags) error {
	data, err := yaml.Marshal(flags)
	if err != nil {
		return err
	}
	return os.WriteFile(flags.CfgFile, data, 0o600)
}
