{"command":"cat > app/node.go <<'EOF'
package app

import (
	"path/filepath"
	"strings"
	"time"
)

type Node struct {
	Name           string
	Path           string
	Parent         *Node
	Children       []*Node
	IsDir          bool
	Archive        bool
	OwnSize        int64
	OwnUsage       int64
	TotalSize      int64
	TotalUsage     int64
	Mtime          time.Time
	OwnMtime       time.Time
	Mli            uint64
	Flag           byte
	NotReg         bool
	IsHardlink     bool
	AlreadyCounted bool
	ReadErr        bool
	ItemCount      int
	DBID           int64
	Marked         bool
	Ignored        bool
}

func (n *Node) DisplaySize(apparent bool) int64 {
	if apparent {
		if n.IsDir {
			return n.TotalSize
		}
		return n.OwnSize
	}
	if n.IsDir {
		return n.TotalUsage
	}
	return n.OwnUsage
}

func (n *Node) DisplayUsage() int64 { return n.DisplaySize(false) }
func (n *Node) DisplayApparent() int64 { return n.DisplaySize(true) }

func (n *Node) fullPath() string {
	if n.Path != "" {
		return n.Path
	}
	if n.Parent == nil {
		return n.Name
	}
	parts := []string{}
	for cur := n; cur != nil; cur = cur.Parent {
		parts = append([]string{cur.Name}, parts...)
	}
	// First part is a root path (possibly absolute); join rest onto it.
	p := parts[0]
	for _, part := range parts[1:] {
		p = filepath.Join(p, part)
	}
	return p
}

func (n *Node) setChildPath() {
	if n.Parent != nil {
		n.Path = filepath.Join(n.Parent.fullPath(), n.Name)
	}
}

// finalize computes TotalSize/TotalUsage, aggregated Mtime and ItemCount
// for a subtree. Marked duplicates contribute zero to ancestors.
func finalizeNode(n *Node) {
	if !n.IsDir {
		n.TotalSize = n.OwnSize
		n.TotalUsage = n.OwnUsage
		n.Mtime = n.OwnMtime
		n.ItemCount = 1
		return
	}
	latest := n.OwnMtime
	totalSize := int64(4096)
	totalUsage := int64(4096)
	count := 0
	for _, child := range n.Children {
		finalizeNode(child)
		if child.Mtime.After(latest) {
			latest = child.Mtime
		}
		count += child.ItemCount
		if child.IsDir {
			totalSize += child.TotalSize
			totalUsage += child.TotalUsage
		} else if !child.AlreadyCounted {
			totalSize += child.OwnSize
			totalUsage += child.OwnUsage
		}
	}
	n.Mtime = latest
	n.TotalSize = totalSize
	n.TotalUsage = totalUsage
	n.ItemCount = count
	if n.Archive {
		n.Flag = 'Z'
		return
	}
	if n.Flag == 'Z' || n.Flag == '!' {
		return
	}
	if n.ReadErr {
		n.Flag = '!'
		return
	}
	if len(n.Children) == 0 {
		// Nodes loaded from storage/import may already have a flag set.
		if n.Flag == 0 || n.Flag == ' ' {
			// Caller decides whether empty dirs receive 'e'; scanners prefer it,
			// JSON import does not. finalizeNode is scanner-oriented and import
			// overrides after calling it where needed.
			n.Flag = 'e'
		}
		return
	}
	if n.Flag == 'e' {
		n.Flag = ' '
	}
	for _, child := range n.Children {
		if child.IsDir && (child.Flag == '!' || child.Flag == '.') {
			n.Flag = '.'
			return
		}
	}
	if n.Flag == '.' {
		n.Flag = ' '
	}
}

// descendantCount returns number of nodes below n.
func descendantCount(n *Node) int {
	if !n.IsDir {
		return 0
	}
	total := 0
	for _, c := range n.Children {
		total++
		total += descendantCount(c)
	}
	return total
}

// compareNatural compares two names using numeric runs naturally.
func compareNatural(a, b string) int {
	ar := []rune(a)
	br := []rune(b)
	ai, bi := 0, 0
	for ai < len(ar) && bi < len(br) {
		ad := ar[ai] >= '0' && ar[ai] <= '9'
		bd := br[bi] >= '0' && br[bi] <= '9'
		if ad && bd {
			as := ai
			for ai < len(ar) && ar[ai] >= '0' && ar[ai] <= '9' {
				ai++
			}
			bs := bi
			for bi < len(br) && br[bi] >= '0' && br[bi] <= '9' {
				bi++
			}
			an := strings.TrimLeft(string(ar[as:ai]), "0")
			bn := strings.TrimLeft(string(br[bs:bi]), "0")
			if an == "" {
				an = "0"
			}
			if bn == "" {
				bn = "0"
			}
			if len(an) != len(bn) {
				if len(an) < len(bn) {
					return -1
				}
				return 1
			}
			if an != bn {
				if an < bn {
					return -1
				}
				return 1
			}
			continue
		}
		if ar[ai] != br[bi] {
			if ar[ai] < br[bi] {
				return -1
			}
			return 1
		}
		ai++
		bi++
	}
	switch {
	case ai < len(ar):
		return 1
	case bi < len(br):
		return -1
	}
	// Naturally equal (only leading-zero differences may remain).
	return strings.Compare(a, b)
}

func (n *Node) flagString() string {
	if n.Flag == 0 {
		return " "
	}
	return string([]byte{n.Flag})
}
