cat > app/filters.go <<'EOF'
package app

import (
	"fmt"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"time"
)

type timeFilter struct {
	hasSince bool
	since    time.Time
	hasUntil bool
	until    time.Time
	hasMax   bool
	maxAge   time.Duration
	hasMin   bool
	minAge   time.Duration
	now      time.Time
}

func parseTimeValue(name, value string) (time.Time, bool, error) {
	// Date only first so callers can expand until to end-of-day.
	if t, err := time.Parse("2006-01-02", value); err == nil {
		return t, true, nil
	}
	if t, err := time.Parse(time.RFC3339, value); err == nil {
		return t, false, nil
	}
	return time.Time{}, false, fmt.Errorf("invalid --%s value: invalid time value %q. Use RFC3339 timestamp or YYYY-MM-DD", name, value)
}

func parseDurationValue(name, raw string) (time.Duration, error) {
	normalized := strings.ReplaceAll(strings.ToLower(raw), " ", "")
	pattern := `^([0-9]+(y|mo|w|d|h|m|s))+$`
	if !regexp.MustCompile(pattern).MatchString(normalized) {
		return 0, fmt.Errorf("invalid --%s value: invalid duration format %q. Use combinations like 7d, 2h30m, 1y2mo", name, normalized)
	}
	units := []struct {
		suffix string
		mult   time.Duration
	}{
		{"mo", 30 * 24 * time.Hour},
		{"y", 365 * 24 * time.Hour},
		{"w", 7 * 24 * time.Hour},
		{"d", 24 * time.Hour},
		{"h", time.Hour},
		{"m", time.Minute},
		{"s", time.Second},
	}
	var total time.Duration
	rest := normalized
	for len(rest) > 0 {
		i := 0
		for i < len(rest) && rest[i] >= '0' && rest[i] <= '9' {
			i++
		}
		numStr := rest[:i]
		num, err := strconv.Atoi(numStr)
		if err != nil {
			return 0, fmt.Errorf("invalid --%s value: invalid number in duration: %s", name, numStr)
		}
		rest = rest[i:]
		matched := false
		for _, u := range units {
			if strings.HasPrefix(rest, u.suffix) {
				total += time.Duration(num) * u.mult
				rest = rest[len(u.suffix):]
				matched = true
				break
			}
		}
		if !matched {
			return 0, fmt.Errorf("invalid --%s value: invalid duration format %q. Use combinations like 7d, 2h30m, 1y2mo", name, normalized)
		}
	}
	return total, nil
}

func makeTimeFilter(f *Flags) (*timeFilter, error) {
	tf := &timeFilter{now: time.Now()}
	if f.Since != "" {
		t, _, err := parseTimeValue("since", f.Since)
		if err != nil {
			return nil, err
		}
		tf.hasSince = true
		tf.since = t
	}
	if f.Until != "" {
		t, isDate, err := parseTimeValue("until", f.Until)
		if err != nil {
			return nil, err
		}
		tf.hasUntil = true
		if isDate {
			t = t.Add(24*time.Hour - time.Nanosecond)
		}
		tf.until = t
	}
	if f.MaxAge != "" {
		d, err := parseDurationValue("max-age", f.MaxAge)
		if err != nil {
			return nil, err
		}
		tf.hasMax = true
		tf.maxAge = d
	}
	if f.MinAge != "" {
		d, err := parseDurationValue("min-age", f.MinAge)
		if err != nil {
			return nil, err
		}
		tf.hasMin = true
		tf.minAge = d
	}
	return tf, nil
}

func (tf *timeFilter) exclude(mtime time.Time) bool {
	if tf == nil {
		return false
	}
	if tf.hasSince && mtime.Before(tf.since) {
		return true
	}
	if tf.hasUntil && mtime.After(tf.until) {
		return true
	}
	if tf.hasMax && mtime.Before(tf.now.Add(-tf.maxAge)) {
		return true
	}
	if tf.hasMin && mtime.After(tf.now.Add(-tf.minAge)) {
		return true
	}
	return false
}

func normalizeTypeFilter(values []string) map[string]bool {
	if len(values) == 0 {
		return nil
	}
	m := make(map[string]bool, len(values))
	for _, v := range values {
