package app

import (
	"fmt"
	"strconv"
	"strings"
)

var useColorOutput bool

func colorWrap(code, s string) string {
	if !useColorOutput {
		return s
	}
	return "\x1b[" + code + "m" + s + "\x1b[0;22m"
}

func yellowNum(s string) string { return colorWrap("33;1", s) }
func blueBold(s string) string  { return colorWrap("34;1", s) }
func redBold(s string) string   { return colorWrap("31;1", s) }

func formatSize(size int64, f *Flags) string {
	if f.NoPrefix {
		return yellowNum(strconv.FormatInt(size, 10))
	}
	if f.ShowInKiB {
		if f.UseSIPrefix {
			return yellowNum(fmt.Sprintf("%.1f", float64(size)/1000.0)) + " kB"
		}
		return yellowNum(fmt.Sprintf("%.1f", float64(size)/1024.0)) + " KiB"
	}
	if f.UseSIPrefix {
		if size < 1000 {
			return yellowNum(strconv.FormatInt(size, 10)) + " B"
		}
		units := []string{"B", "kB", "MB", "GB", "TB", "PB", "EB"}
		value := float64(size)
		idx := 0
		for value >= 1000 && idx < len(units)-1 {
			value /= 1000
			idx++
		}
		return yellowNum(fmt.Sprintf("%.1f", value)) + " " + units[idx]
	}
	if size < 1024 {
