{"command":"cat > app/analyze.go <<'EOF'
package app

import (
	"archive/zip"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"syscall"
	"time"
)

type scanner struct {
	flags         *Flags
	ignoreDirs    map[string]bool
	pattern       *regexp.Regexp
	patternStrs   []string
	timeF         *timeFilter
	typeF         *typeFilter
	seen          map[uint64]bool
	sequential    bool
	sqlite        bool
	progressFunc  func()
	itemsScanned  int
	currentPath   string
	rootPath      string
	storageSeq    bool
	pendingIgnLog []string
}

func compileIgnorePatterns(patterns []string) (*regexp.Regexp, error) {
	for _, p := range patterns {
		if _, err := regexp.Compile(p); err != nil {
			return nil, err
		}
	}
	if len(patterns) == 0 {
		return nil, nil
	}
	combined := "^" + strings.Join(patterns, "|")
	re, err := regexp.Compile(combined)
	if err != nil {
		return nil, err
	}
	return re, nil
}

func newScanner(flags *Flags, ignoreDirs []string, pattern *regexp.Regexp, patterns []string, tf *timeFilter) *scanner {
	m := make(map[string]bool, len(ignoreDirs))
	for _, d := range ignoreDirs {
		m[d] = true
	}
	return &scanner{
		flags:       flags,
		ignoreDirs:  m,
		pattern:     pattern,
		patternStrs: patterns,
		timeF:       tf,
		typeF: &typeFilter{
			include: normalizeTypeFilter(flags.TypeFilter),
			exclude: normalizeTypeFilter(flags.ExcludeTypeFilter),
		},
		seen:       make(map[uint64]bool),
		sequential: flags.SequentialScanning,
	}
}

func (s *scanner) shouldIgnoreDir(path, name string) bool {
	if s.ignoreDirs[path] {
		return true
	}
	if s.pattern != nil && s.pattern.MatchString(path) {
		return true
	}
	if s.flags.NoHidden && strings.HasPrefix(name, ".") {
		return true
	}
	return false
}

func diskUsage(info os.FileInfo) int64 {
	if st, ok := info.Sys().(*syscall.Stat_t); ok {
		return st.Blocks * 512
	}
	return 0
}

func isSymlinkOrSocket(info os.FileInfo) bool {
	m := info.Mode()
	return m&os.ModeSymlink != 0 || m&os.ModeSocket != 0
}

func (s *scanner) makeFileNode(parent *Node, entryPath, name string, entry os.DirEntry) *Node {
	// Type filter is checked based on name before stat in the reference.
	if s.typeF != nil && s.typeF.excluded(name) {
		ext := filepath.Ext(name)
		if len(s.flags.TypeFilter) > 0 {
			if ext != "" {
				logInfo("File %s excluded by type filter", name)
			}
		} else if len(s.flags.ExcludeTypeFilter) > 0 {
			logInfo("File %s ignored by type", name)
		}
		return nil
	}

	lstatInfo, err := os.Lstat(entryPath)
	if err != nil {
		logInfo("%s", err.Error())
		return nil
	}
	info := lstatInfo
	annexSize := int64(-1)
	if s.flags.FollowSymlinks && lstatInfo.Mode()&os.ModeSymlink != 0 {
		statInfo, statErr := os.Stat(entryPath)
		if statErr != nil {
			if s.flags.ShowAnnexedSize {
				if target, rerr := os.Readlink(entryPath); rerr == nil && strings.Contains(target, ".git/annex/objects") {
					annexSize = parseAnnexSize(target)
				}
			}
			if annexSize < 0 {
				return nil
			}
			// keep lstat info for an annexed (dangling) link
		} else if !statInfo.IsDir() {
			info = statInfo
		}
	}

	node := &Node{
		Name:     name,
		Path:     entryPath,
		Parent:   parent,
		OwnMtime: info.ModTime(),
		Mtime:    info.ModTime(),
		Flag:     ' ',
	}

	if annexSize >= 0 {
		node.OwnSize = annexSize
		node.OwnUsage = 0
		node.NotReg = true
		node.Flag = '@'
	} else if isSymlinkOrSocket(info) {
		node.OwnSize = info.Size()
		node.OwnUsage = 0
		node.NotReg = true
		node.Flag = '@'
	} else if info.Mode().IsRegular() {
		node.OwnSize = info.Size()
		node.OwnUsage = diskUsage(info)
		if st, ok := info.Sys().(*syscall.Stat_t); ok && st.Nlink > 1 {
			node.IsHardlink = true
			node.Mli = st.Ino
			node.Flag = 'H'
			if s.seen[st.Ino] {
				node.AlreadyCounted = true
			} else {
				s.seen[st.Ino] = true
			}
		}
	} else {
		node.OwnSize = info.Size()
		node.OwnUsage = diskUsage(info)
	}

	if s.timeF != nil && s.timeF.exclude(info.ModTime()) {
		return nil
	}
	s.itemsScanned++
	s.currentPath = entryPath
	if s.progressFunc != nil {
		s.progressFunc()
	}
	return node
}

func parseAnnexSize(target string) int64 {
	base := filepath.Base(target)
	parts := strings.Split(base, "-s")
	if len(parts) < 2 {
		return 0
	}
	token := strings.Split(parts[1], "-")[0]
	size, err := strconv.ParseInt(token, 10, 64)
	if err != nil {
		return 0
	}
	return size
}

func (s *scanner) scanDir(node *Node, path string) {
	s.currentPath = path
	entries, err := os.ReadDir(path)
	if err != nil {
		node.ReadErr = true
		node.Flag = '!'
		logInfo("%s", err.Error())
		return
	}

	if s.storageSeq || s.sequential {
		for _, entry := range entries {
			s.processEntry(node, path, entry)
		}
		return
	}

	// Deterministic equivalent of parallel scanning: files in this
	// directory first, then sub-directories in entry order.
	var dirs []os.DirEntry
	var archives []os.DirEntry
	for _, entry := range entries {
		if entry.IsDir() {
			dirs = append(dirs, entry)
			continue
		}
		if s.isArchive(entry.Name()) {
			archives = append(archives, entry)
			continue
		}
		s.processEntry(node, path, entry)
	}
	for _, entry := range dirs {
		s.processEntry(node, path, entry)
	}
	for _, entry := range archives {
		s.processEntry(node, path, entry)
	}
}

func (s *scanner) isArchive(name string) bool {
	if !s.flags.ArchiveBrowsing {
		return false
	}
	lower := strings.ToLower(name)
	return strings.HasSuffix(lower, ".zip") || strings.HasSuffix(lower, ".jar")
}

func (s *scanner) processEntry(parent *Node, dirPath string, entry os.DirEntry) {
	name := entry.Name()
	entryPath := filepath.Join(dirPath, name)

	if entry.IsDir() {
		if s.shouldIgnoreDir(entryPath, name) {
			logInfo("Directory %s ignored", entryPath)
			return
		}
		info, err := entry.Info()
		var mtime time.Time
		if err == nil {
			mtime = info.ModTime()
		} else {
			// fall back to lstat
			if li, lerr := os.Lstat(entryPath); lerr == nil {
				mtime = li.ModTime()
			}
		}
		child := &Node{
			Name: name, Path: entryPath, Parent: parent, IsDir: true,
			OwnSize: 4096, OwnUsage: 4096, OwnMtime: mtime, Mtime: mtime, Flag: ' ',
		}
		parent.Children = append(parent.Children, child)
		s.itemsScanned++
		s.scanDir(child, entryPath)
		return
	}

	// Archive files are treated as directories when browsing is enabled.
	if s.isArchive(name) {
		if archiveNode := s.tryArchive(parent, entryPath, name, entry); archiveNode != nil {
			return
		}
		// fall through as regular file when the archive cannot be read
	}

	if fileNode := s.makeFileNode(parent, entryPath, name, entry); fileNode != nil {
		parent.Children = append(parent.Children, fileNode)
	}
}

func (s *scanner) tryArchive(parent *Node, entryPath, name string, entry os.DirEntry) *Node {
	// The file itself is subject to type/time filters, but its
	// contents are not. Reuse file-node creation only for validation:
	// create a probe file node in a sandbox seen-map state is complex,
	// so validate the cheap checks directly.
	if s.typeF != nil && s.typeF.excluded(name) {
		ext := filepath.Ext(name)
		if len(s.flags.TypeFilter) > 0 {
			if ext != "" {
				logInfo("File %s excluded by type filter", name)
			}
		} else if len(s.flags.ExcludeTypeFilter) > 0 {
			logInfo("File %s ignored by type", name)
		}
		return &Node{} // non-nil sentinel: consumed
	}
	info, err := os.Lstat(entryPath)
	if err != nil {
		return nil
	}
	// Only regular files can be archives (a symlink named *.zip is a link).
	if !info.Mode().IsRegular() {
		return nil
	}
	if s.timeF != nil && s.timeF.exclude(info.ModTime()) {
		return &Node{}
	}
	reader, err := zip.OpenReader(entryPath)
	if err != nil {
		return nil
	}
	defer reader.Close()

	archiveNode := &Node{
		Name: name, Path: entryPath, Parent: parent, IsDir: true, Archive: true,
		OwnSize: 4096, OwnUsage: 4096, OwnMtime: info.ModTime(), Mtime: info.ModTime(), Flag: 'Z',
	}
	parent.Children = append(parent.Children, archiveNode)
	s.buildArchiveTree(archiveNode, &reader.Reader)
	return archiveNode
}

func (s *scanner) buildArchiveTree(root *Node, reader *zip.Reader) {
	dirMap := map[string]*Node{"": root}
	getDir := func(dir string, mtime time.Time) *Node {
		dir = strings.TrimSuffix(dir, "/")
		if dir == "" || dir == "." {
			return root
		}
		if existing, ok := dirMap[dir]; ok {
			return existing
		}
		parts := strings.Split(dir, "/")
		cur := root
		curPath := ""
		for _, part := range parts {
			if part == "" || part == "." {
				continue
			}
			if curPath == "" {
				curPath = part
			} else {
				curPath = curPath + "/" + part
			}
			if existing, ok := dirMap[curPath]; ok {
				cur = existing
				continue
			}
			child := &Node{
				Name: part, Parent: cur, IsDir: true,
				OwnSize: 4096, OwnUsage: 4096, OwnMtime: mtime, Mtime: mtime, Flag: ' ',
			}
			child.Path = filepath.Join(cur.fullPath(), part)
			cur.Children = append(cur.Children, child)
			dirMap[curPath] = child
			cur = child
		}
		return cur
	}

	for _, zf := range reader.File {
		mtime := zf.Modified
		name := zf.Name
		if strings.HasSuffix(name, "/") {
			d := getDir(name, mtime)
			if d != root {
				d.OwnMtime = mtime
				d.Mtime = mtime
			}
			continue
		}
		dirPart := ""
		base := name
		if idx := strings.LastIndex(name, "/"); idx >= 0 {
			dirPart = name[:idx]
			base = name[idx+1:]
		}
		if base == "" {
			continue
		}
		parent := getDir(dirPart, mtime)
		size := int64(zf.UncompressedSize64)
		child := &Node{
			Name: base, Parent: parent, OwnSize: size, OwnUsage: size,
			OwnMtime: mtime, Mtime: mtime, Flag: ' ',
		}
		child.Path = filepath.Join(parent.fullPath(), base)
		parent.Children = append(parent.Children, child)
		s.itemsScanned++
	}
}

func (s *scanner) analyze(rootPath string) *Node {
	var mtime time.Time
	if info, err := os.Stat(rootPath); err == nil {
		mtime = info.ModTime()
	}
	root := &Node{
		Name: rootPath, Path: rootPath, IsDir: true,
		OwnSize: 4096, OwnUsage: 4096, OwnMtime: mtime, Mtime: mtime, Flag: ' ',
	}
	s.rootPath = rootPath
	s.scanDir(root, rootPath)
	finalizeNode(root)
	return root
}
EOF
gofmt -w app/analyze.go"}

