func run(cmd *cobra.Command, args []string, cli *cliValues) error {
	flags := defaultFlags()
	flags.CfgFile = resolveCfgFile(cli.cfgFileFlag)
	cfgErr := loadConfig(&flags)
	// Write-config carries the resolved config path (not a config value).
	flags.CfgFile = resolveCfgFile(cli.cfgFileFlag)
	applyChangedFlags(cmd, &flags, cli)

	if flags.WriteConfig {
		if err := writeConfigFile(&flags); err != nil {
			return fmt.Errorf("error writing config file %s: %w", flags.CfgFile, err)
		}
	}

	logFile, err := openLogFile(flags.LogFile)
	if err != nil {
		return fmt.Errorf("opening log file: %w", err)
	}
	defer logFile.Close()
	setLogOutput(logFile)
	if cfgErr != nil {
		logInfo("Error reading config file: %s", cfgErr.Error())
	}

	if flags.ShowVersion {
		fmt.Fprint(cmd.OutOrStdout(), versionText)
		return nil
	}

	logInfo("Runtime flags: %+v", flags)

	if flags.NoPrefix && flags.UseSIPrefix {
		return errors.New("--no-prefix and --si cannot be used at once")
	}

	if flags.Profiling {
		go func() {
			_ = http.ListenAndServe("localhost:6060", nil)
		}()
	}

	// Determine scan path (absolute) early; used for mount points.
	scanArg := "."
	if len(args) > 0 {
		scanArg = args[0]
	}
	absPath, err := filepath.Abs(scanArg)
	if err != nil {
		absPath = scanArg
	}

	// Open output file.
	var outputWriter *os.File
	var outWriter = cmd.OutOrStdout()
	exporting := false
	var exportWriter *os.File
	if flags.OutputFile != "" {
		exporting = true
		if flags.OutputFile == "-" {
			exportWriter = os.Stdout
		} else {
			f, err := os.OpenFile(flags.OutputFile, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o600)
			if err != nil {
				return fmt.Errorf("opening output file: %w", err)
			}
			outputWriter = f
			exportWriter = f
			defer f.Close()
		}
	}
	_ = outputWriter

	// Create SQLite database eagerly (as in the reference).
	backend := ""
	if flags.DbPath != "" {
		if strings.HasSuffix(flags.DbPath, ".badger") {
			backend = "badger"
		} else {
			backend = "sqlite"
		}
	}
	var sqliteDB *sqliteStorage
	if backend == "sqlite" {
		sdb, err := openSQLite(flags.DbPath, flags.ReadFromStorage)
		if err != nil {
			return fmt.Errorf("creating sqlite analyzer: %w", err)
		}
		sqliteDB = sdb
		defer sdb.close()
	}

	// Time filter validation (after SQLite creation, before other setup).
	tf, err := makeTimeFilter(&flags)
	if err != nil {
		return fmt.Errorf("invalid time filter: %w", err)
	}

	// Analyzer setup (logging in reference order).
	ignoreDirs := make([]string, len(flags.IgnoreDirs))
	copy(ignoreDirs, flags.IgnoreDirs)
	// Convert relative ignore dirs to absolute.
	for i, d := range ignoreDirs {
		if !filepath.IsAbs(d) {
			if abs, err := filepath.Abs(d); err == nil {
				ignoreDirs[i] = abs
			}
		}
	}
	if flags.NoCross {
		mounts := mountPointsUnder(absPath)
		logInfo("Ignoring mount points: %s", strings.Join(mounts, ", "))
		ignoreDirs = append(ignoreDirs, mounts...)
	}
	if len(flags.TypeFilter) > 0 {
		logInfo("Including only file types: %s", strings.Join(flags.TypeFilter, ", "))
	}
	if len(flags.ExcludeTypeFilter) > 0 {
		logInfo("Ignoring file types: %s", strings.Join(flags.ExcludeTypeFilter, ", "))
	}
	logInfo("Ignoring dirs %s", strings.Join(ignoreDirs, ", "))

	patterns := flags.IgnoreDirPatterns
	var ignorePatterncompiled = (*struct{})(nil)
	_ = ignorePatterncompiled
	patternRe, err := func() (interface{ MatchString(string) bool }, error) { return nil, nil }()
	_ = patternRe
	// Compile ignore patterns (validating each first).
	compiledPattern, err := compileIgnorePatterns(patterns)
	if len(patterns) > 0 {
		logInfo("Ignoring dir patterns %s", strings.Join(patterns, ", "))
	}
	if err != nil {
		return err
	}
	if flags.IgnoreFromFile != "" {
		logInfo("Reading ignoring dir patterns from file '%s'", flags.IgnoreFromFile)
		filePatterns, err := readIgnoreFromFile(flags.IgnoreFromFile)
		if err != nil {
			return err
		}
		compiledPattern, err = compileIgnorePatterns(filePatterns)
		if err != nil {
			return err
		}
		patterns = filePatterns
	}
	if flags.NoHidden {
		logInfo("Ignoring hidden dirs")
	}
	if flags.MaxCores > 0 && flags.MaxCores <= runtime.NumCPU() {
		runtime.GOMAXPROCS(flags.MaxCores)
		logInfo("Max cores set to %d", flags.MaxCores)
	}

	// Colour for plain stdout output.
	stdoutIsTTY := isTTY(os.Stdout)
	useColorOutput = !flags.NoColor && stdoutIsTTY
	if cf := os.Getenv("NO_COLOR"); cf != "" {
		// The reference (via fatih/color style libraries) honours NO_COLOR
		// only through its own flag in practice; keep colour controlled
		// solely by --no-color/tty to match observed script(1) output.
		_ = cf
	}

	nonInteractive := flags.NonInteractive || !stdoutIsTTY || exporting

	// --- Show disks branch ---
	if flags.ShowDisks {
		if exporting {
			return errors.New("loading mount points: exporting devices list is not supported")
		}
		if nonInteractive {
			printDevices(outWriter, &flags)
			return nil
		}
		return runDisksTUI(&flags)
	}

	// --- Import branch ---
	if flags.InputFile != "" {
		if exporting {
			return errors.New("reading analysis: reading analysis is not possible while exporting")
		}
		var reader *os.File
		if flags.InputFile == "-" {
			reader = os.Stdin
		} else {
			f, err := os.Open(flags.InputFile)
			if err != nil {
				return fmt.Errorf("opening input file: %w", err)
			}
			defer f.Close()
			reader = f
		}
		// Reading analysis runs in a goroutine in the reference
		// (panics there show a goroutine trace); do the same.
		type result struct {
			root *Node
			err  error
		}
		ch := make(chan result, 1)
		go func() {
			root, err := readAnalysis(reader)
			ch <- result{root, err}
		}()
		res := <-ch
		if res.err != nil {
			return fmt.Errorf("reading analysis: %w", res.err)
		}
		if nonInteractive {
			printNonInteractive(outWriter, res.root, &flags, true)
			return nil
		}
		return runTUI(res.root, &flags, absPath, backend, sqliteDB, ignoreDirs, compiledPattern, patterns, tf)
	}

	// --- Scan / read-from-storage branch ---
	if _, err := os.Stat(absPath); err != nil {
		return err
	}
	logInfo("Analyzing path: %s", absPath)

	var root *Node
	readFromDB := false
	if flags.ReadFromStorage && backend == "sqlite" && sqliteDB != nil {
		if sqliteDB.hasData() {
			logInfo("Loading analysis from existing SQLite database")
			r, err := sqliteDB.loadTree()
			if err == nil && r != nil {
				root = r
				readFromDB = true
			}
		}
	}
	if flags.ReadFromStorage && backend == "badger" {
		if r, err := loadBadgerTree(flags.DbPath); err == nil && r != nil {
			root = r
			readFromDB = true
		}
	}

	if !readFromDB {
		scan := newScanner(&flags, ignoreDirs, compiledPattern, patterns, tf)
		if backend == "badger" || backend == "sqlite" {
			scan.storageSeq = true
		}
		if !nonInteractive {
			// TUI performs its own scan with progress.
			return runTUIWithScan(&flags, absPath, backend, sqliteDB, scan, exporting, exportWriter)
		}
		// Non-interactive scan, optionally with a spinner.
		var spin *spinner
		if !flags.NoProgress && stdoutIsTTY {
			text := "Calculating disk usage..."
			if exporting {
				text = "Writing output file..."
			}
			spin = startSpinner(os.Stdout, text)
		}
		scanDone := make(chan *Node, 1)
		go func() {
			scanDone <- scan.analyze(absPath)
		}()
		root = <-scanDone
		if spin != nil {
			spin.stop()
		}
		if backend == "sqlite" && sqliteDB != nil {
			if err := sqliteDB.storeTree(root, absPath); err != nil {
				return err
			}
			// Reload so display reflects SQLite transformations.
			if r, err := sqliteDB.loadTree(); err == nil && r != nil {
				root = r
			}
		}
		if backend == "badger" {
			if err := saveBadgerTree(flags.DbPath, root, absPath, flags.ReadFromStorage); err != nil {
				return err
			}
		}
		if exporting {
			if err := exportAnalysis(exportWriter, root, backend); err != nil {
				return fmt.Errorf("scanning dir: %w", err)
			}
			return nil
		}
		printNonInteractive(outWriter, root, &flags, false)
		return nil
	}

	// Read from storage.
	if exporting {
		if err := exportAnalysis(exportWriter, root, backend); err != nil {
			return fmt.Errorf("scanning dir: %w", err)
		}
		return nil
	}
	if nonInteractive {
		printNonInteractive(outWriter, root, &flags, false)
		return nil
	}
	return runTUI(root, &flags, absPath, backend, sqliteDB, ignoreDirs, compiledPattern, patterns, tf)
}

func readIgnoreFromFile(path string) ([]string, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	var lines []string
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		lines = append(lines, scanner.Text())
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}
	return lines, nil
}
