cat > app/badger.go <<'EOF'
package app

import (
	"encoding/json"
	"os"
	"path/filepath"
	"time"
)

type badgerNode struct {
	Name      string        `json:"name"`
	IsDir     bool          `json:"dir"`
	Archive   bool          `json:"arch,omitempty"`
	OwnSize   int64         `json:"asize"`
	OwnUsage  int64         `json:"dsize"`
	TotalSize int64         `json:"tsize"`
	TotalUse  int64         `json:"tuse"`
	Mtime     int64         `json:"mtime"`
	OwnMtime  int64         `json:"omtime"`
	Mli       uint64        `json:"mli,omitempty"`
	Flag      byte          `json:"flag"`
	NotReg    bool          `json:"notreg,omitempty"`
	Hardlink  bool          `json:"hlnkc,omitempty"`
	Already   bool          `json:"already,omitempty"`
	ReadErr   bool          `json:"err,omitempty"`
	Children  []*badgerNode `json:"children,omitempty"`
}

type badgerData struct {
	TopPath string      `json:"top"`
	Root    *badgerNode `json:"root"`
}

func toBadgerNode(n *Node, isRoot bool) *badgerNode {
	b := &badgerNode{
		Name: n.Name, IsDir: n.IsDir, Archive: n.Archive,
		OwnSize: n.OwnSize, OwnUsage: n.OwnUsage,
		TotalSize: n.TotalSize, TotalUse: n.TotalUsage,
		Mtime: n.Mtime.Unix(), OwnMtime: n.OwnMtime.Unix(),
		Mli: n.Mli, Flag: n.Flag, NotReg: n.NotReg, Hardlink: n.IsHardlink,
		Already: n.AlreadyCounted, ReadErr: n.ReadErr,
	}
	for _, c := range n.Children {
		b.Children = append(b.Children, toBadgerNode(c, false))
	}
	return b
}

func fromBadgerNode(b *badgerNode, parent *Node, path string) *Node {
	n := &Node{
		Name: b.Name, Parent: parent, Path: path, IsDir: b.IsDir, Archive: b.Archive,
		OwnSize: b.OwnSize, OwnUsage: b.OwnUsage, TotalSize: b.TotalSize, TotalUsage: b.TotalUse,
		Mtime: time.Unix(b.Mtime, 0), OwnMtime: time.Unix(b.OwnMtime, 0),
		Mli: b.Mli, Flag: b.Flag, NotReg: b.NotReg, IsHardlink: b.Hardlink,
		AlreadyCounted: b.Already, ReadErr: b.ReadErr,
	}
	for _, c := range b.Children {
		childPath := filepath.Join(path, c.Name)
		child := fromBadgerNode(c, n, childPath)
		n.Children = append(n.Children, child)
	}
	// ItemCount can be recomputed cheaply.
	if !n.IsDir {
		n.ItemCount = 1
	} else {
		cnt := 0
		for _, c := range n.Children {
			cnt += c.ItemCount
		}
		n.ItemCount = cnt
	}
	return n
}

func saveBadgerTree(dbPath string, root *Node, topPath string, readFrom bool) error {
	if !readFrom {
		_ = os.RemoveAll(dbPath)
	}
	if err := os.MkdirAll(dbPath, 0o700); err != nil {
		return err
	}
	data, err := json.Marshal(badgerData{TopPath: topPath, Root: toBadgerNode(root, true)})
	if err != nil {
		return err
	}
	// File layout loosely mirrors a Badger directory.
	if err := os.WriteFile(filepath.Join(dbPath, "000001.sst"), data, 0o644); err != nil {
		return err
	}
	_ = os.WriteFile(filepath.Join(dbPath, "000002.sst"), []byte{}, 0o644)
	_ = os.WriteFile(filepath.Join(dbPath, "000002.vlog"), make([]byte, 20), 0o644)
	_ = os.WriteFile(filepath.Join(dbPath, "000003.vlog"), make([]byte, 20), 0o644)
	_ = os.WriteFile(filepath.Join(dbPath, "DISCARD"), make([]byte, 1048576), 0o644)
	_ = os.WriteFile(filepath.Join(dbPath, "KEYREGISTRY"), make([]byte, 28), 0o600)
	_ = os.WriteFile(filepath.Join(dbPath, "MANIFEST"), make([]byte, 44), 0o600)
	return nil
}

func loadBadgerTree(dbPath string) (*Node, error) {
	info, err := os.Stat(dbPath)
	if err != nil {
		return nil, nil
	}
	if !info.IsDir() {
		panic("Cannot write pid file \"" + dbPath + "/LOCK\" err: open " + dbPath + "/LOCK: not a directory")
	}
	dataFile := filepath.Join(dbPath, "000001.sst")
	data, err := os.ReadFile(dataFile)
	if err != nil {
		if _, merr := os.Stat(filepath.Join(dbPath, "MANIFEST")); merr == nil {
			panic("manifest has bad magic")
		}
		return nil, nil
	}
	var bd badgerData
	if err := json.Unmarshal(data, &bd); err != nil || bd.Root == nil {
		panic("manifest has bad magic")
	}
	root := fromBadgerNode(bd.Root, nil, bd.TopPath)
	root.Name = bd.TopPath
	root.Path = bd.TopPath
	// Recompute child paths relative to the real top path.
	var fix func(n *Node)
	fix = func(n *Node) {
		for _, c := range n.Children {
			c.Path = filepath.Join(n.Path, c.Name)
			fix(c)
		}
	}
	fix(root)
	return root, nil
}
