		_ = s.exec("ROLLBACK")
		return err
	}
	metaSQL := "INSERT INTO metadata(key, value) VALUES('top_dir_path', ?)"
	var mstmt *C.sqlite3_stmt
	cm := C.CString(metaSQL)
	rc = C.sqlite3_prepare_v2(s.db, cm, -1, &mstmt, nil)
	C.free(unsafe.Pointer(cm))
	if rc != C.SQLITE_OK {
		_ = s.exec("ROLLBACK")
		return sqliteErr(s.db, rc)
	}
