import "C"

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"time"
	"unsafe"
)

type sqliteStorage struct {
	db   *C.sqlite3
	path string
}

const sqliteSchema = `
CREATE TABLE IF NOT EXISTS items (
		id          INTEGER PRIMARY KEY,
		parent_id   INTEGER REFERENCES items(id),
		name        TEXT NOT NULL,
		is_dir      INTEGER NOT NULL,
		size        INTEGER NOT NULL,
		usage       INTEGER NOT NULL,
		mtime       INTEGER NOT NULL,
		item_count  INTEGER NOT NULL DEFAULT 1,
		mli         INTEGER NOT NULL DEFAULT 0,
		flag        TEXT NOT NULL DEFAULT ' '
	);
CREATE INDEX IF NOT EXISTS idx_items_parent_id ON items(parent_id);
CREATE INDEX IF NOT EXISTS idx_items_mli ON items(mli) WHERE mli != 0;
CREATE TABLE IF NOT EXISTS metadata (
		key   TEXT PRIMARY KEY,
		value TEXT
	);
`

func sqliteErr(db *C.sqlite3, rc C.int) error {
	if rc == 14 { // SQLITE_CANTOPEN
		return errors.New("unable to open database file: out of memory (14)")
	}
	msg := C.GoString(C.sqlite3_errmsg(db))
	return fmt.Errorf("%s (%d)", msg, int(rc))
}

func openSQLite(path string, readFrom bool) (*sqliteStorage, error) {
	if !readFrom {
		_ = os.Remove(path)
	}
	cpath := C.CString(path)
	defer C.free(unsafe.Pointer(cpath))
	var db *C.sqlite3
	rc := C.sqlite3_open(cpath, &db)
	if rc != C.SQLITE_OK {
		var err error
		if db != nil {
			err = sqliteErr(db, rc)
			C.sqlite3_close(db)
		} else {
			err = fmt.Errorf("unable to open database file: out of memory (%d)", int(rc))
		}
		return nil, err
	}
	s := &sqliteStorage{db: db, path: path}
	if err := s.exec(sqliteSchema); err != nil {
		C.sqlite3_close(db)
		return nil, err
	}
	return s, nil
}

func (s *sqliteStorage) close() {
	if s.db != nil {
		C.sqlite3_close(s.db)
		s.db = nil
	}
}

func (s *sqliteStorage) exec(sqlText string) error {
	csql := C.CString(sqlText)
	defer C.free(unsafe.Pointer(csql))
	var errmsg *C.char
	rc := C.sqlite3_exec(s.db, csql, nil, nil, &errmsg)
	if rc != C.SQLITE_OK {
		if errmsg != nil {
			msg := C.GoString(errmsg)
			_ = msg
			C.sqlite3_free(unsafe.Pointer(errmsg))
		}
		return sqliteErr(s.db, rc)
	}
	return nil
}

func (s *sqliteStorage) hasData() bool {
	count := 0
	err := s.queryInts("SELECT COUNT(*) FROM items", func(cols []interface{}) {
		count = int(cols[0].(int64))
	})
	return err == nil && count > 0
}

type sqlRowCallback func(cols []interface{})

func (s *sqliteStorage) queryInts(query string, cb sqlRowCallback) error {
	var stmt *C.sqlite3_stmt
	cq := C.CString(query)
	defer C.free(unsafe.Pointer(cq))
	rc := C.sqlite3_prepare_v2(s.db, cq, -1, &stmt, nil)
	if rc != C.SQLITE_OK {
		return sqliteErr(s.db, rc)
	}
	defer C.sqlite3_finalize(stmt)
	for {
		rc = C.sqlite3_step(stmt)
		if rc == C.SQLITE_ROW {
			n := int(C.sqlite3_column_count(stmt))
			cols := make([]interface{}, n)
			for i := 0; i < n; i++ {
				cols[i] = int64(C.sqlite3_column_int64(stmt, C.int(i)))
			}
			cb(cols)
			continue
		}
		if rc == C.SQLITE_DONE {
			return nil
		}
		return sqliteErr(s.db, rc)
	}
}

func (s *sqliteStorage) storeTree(root *Node, topPath string) error {
	if err := s.exec("BEGIN TRANSACTION; DELETE FROM items; DELETE FROM metadata;"); err != nil {
		return err
	}
	insertSQL := "INSERT INTO items(parent_id, name, is_dir, size, usage, mtime, item_count, mli, flag) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)"
	var stmt *C.sqlite3_stmt
	cq := C.CString(insertSQL)
	rc := C.sqlite3_prepare_v2(s.db, cq, -1, &stmt, nil)
	C.free(unsafe.Pointer(cq))
	if rc != C.SQLITE_OK {
		_ = s.exec("ROLLBACK")
		return sqliteErr(s.db, rc)
	}
	defer C.sqlite3_finalize(stmt)

	insert := func(parentID interface{}, n *Node, isRoot bool) (int64, error) {
		C.sqlite3_reset(stmt)
		C.sqlite3_clear_bindings(stmt)
		if parentID == nil {
			C.sqlite3_bind_null(stmt, 1)
		} else {
			C.sqlite3_bind_int64(stmt, 1, C.sqlite3_int64(parentID.(int64)))
		}
		name := n.Name
		if isRoot {
			name = filepath.Base(topPath)
		}
		cname := C.CString(name)
		C.gdu_bind_text(stmt, 2, cname, C.int(len(name)))
		C.free(unsafe.Pointer(cname))
		isDir := 0
		if n.IsDir {
			isDir = 1
		}
		C.sqlite3_bind_int(stmt, 3, C.int(isDir))

		var size, usage int64
		var flagStr string
		var mtime time.Time
		itemCount := 1
		if n.IsDir {
			size = n.TotalSize
			usage = n.TotalUsage
			mtime = n.Mtime
			itemCount = n.ItemCount + 1
			if len(n.Children) == 0 {
				flagStr = "e"
			} else {
				flagStr = " "
			}
			if n.Archive {
				flagStr = "Z"
			}
		} else {
			mtime = n.OwnMtime
			if n.AlreadyCounted && n.Mli != 0 {
				size, usage = 0, 0
				flagStr = "H"
			} else {
				size, usage = n.OwnSize, n.OwnUsage
				if n.NotReg {
					flagStr = "@"
				} else {
					flagStr = " "
				}
			}
		}
		C.sqlite3_bind_int64(stmt, 4, C.sqlite3_int64(size))
		C.sqlite3_bind_int64(stmt, 5, C.sqlite3_int64(usage))
		C.sqlite3_bind_int64(stmt, 6, C.sqlite3_int64(mtime.Unix()))
		C.sqlite3_bind_int64(stmt, 7, C.sqlite3_int64(int64(itemCount)))
		C.sqlite3_bind_int64(stmt, 8, C.sqlite3_int64(int64(n.Mli)))
		cflag := C.CString(flagStr)
		C.gdu_bind_text(stmt, 9, cflag, C.int(len(flagStr)))
		C.free(unsafe.Pointer(cflag))
		if stepRC := C.sqlite3_step(stmt); stepRC != C.SQLITE_DONE {
			return 0, sqliteErr(s.db, stepRC)
		}
		return int64(C.sqlite3_last_insert_rowid(s.db)), nil
	}

	var recurse func(n *Node, parentID interface{}, isRoot bool) error
	recurse = func(n *Node, parentID interface{}, isRoot bool) error {
		id, err := insert(parentID, n, isRoot)
		if err != nil {
			return err
		}
		n.DBID = id
		for _, child := range n.Children {
			if err := recurse(child, id, false); err != nil {
				return err
			}
		}
		return nil
	}
	if err := recurse(root, nil, true); err != nil {
		_ = s.exec("ROLLBACK")
		return err
	}
	metaSQL := "INSERT INTO metadata(key, value) VALUES('top_dir_path', ?)"
	var mstmt *C.sqlite3_stmt
	cm := C.CString(metaSQL)
	rc = C.sqlite3_prepare_v2(s.db, cm, -1, &mstmt, nil)
	C.free(unsafe.Pointer(cm))
	if rc != C.SQLITE_OK {
		_ = s.exec("ROLLBACK")
		return sqliteErr(s.db, rc)
	}
	ctop := C.CString(topPath)
	C.gdu_bind_text(mstmt, 1, ctop, C.int(len(topPath)))
	C.free(unsafe.Pointer(ctop))
	rc = C.sqlite3_step(mstmt)
	C.sqlite3_finalize(mstmt)
	if rc != C.SQLITE_DONE {
		_ = s.exec("ROLLBACK")
		return sqliteErr(s.db, rc)
	}
	return s.exec("COMMIT")
}

type sqliteItemRow struct {
	id        int64
	parentID  int64
	hasParent bool
	name      string
	isDir     bool
	size      int64
	usage     int64
	mtime     int64
	count     int64
	mli       uint64
	flag      string
}

func (s *sqliteStorage) loadTree() (*Node, error) {
	query := "SELECT id, parent_id, name, is_dir, size, usage, mtime, item_count, mli, flag FROM items ORDER BY id"
	var stmt *C.sqlite3_stmt
	cq := C.CString(query)
	rc := C.sqlite3_prepare_v2(s.db, cq, -1, &stmt, nil)
	C.free(unsafe.Pointer(cq))
	if rc != C.SQLITE_OK {
		return nil, sqliteErr(s.db, rc)
	}
	var rows []sqliteItemRow
	for {
		rc = C.sqlite3_step(stmt)
		if rc == C.SQLITE_DONE {
			break
		}
		if rc != C.SQLITE_ROW {
			err := sqliteErr(s.db, rc)
			C.sqlite3_finalize(stmt)
			return nil, err
		}
		r := sqliteItemRow{
			id: int64(C.sqlite3_column_int64(stmt, 0)),
		}
		if C.sqlite3_column_type(stmt, 1) != C.SQLITE_NULL {
			r.parentID = int64(C.sqlite3_column_int64(stmt, 1))
			r.hasParent = true
		}
		if txt := C.gdu_column_text(stmt, 2); txt != nil {
			r.name = C.GoString(txt)
		}
		r.isDir = C.sqlite3_column_int64(stmt, 3) != 0
		r.size = int64(C.sqlite3_column_int64(stmt, 4))
		r.usage = int64(C.sqlite3_column_int64(stmt, 5))
		r.mtime = int64(C.sqlite3_column_int64(stmt, 6))
		r.count = int64(C.sqlite3_column_int64(stmt, 7))
		r.mli = uint64(C.sqlite3_column_int64(stmt, 8))
		if txt := C.gdu_column_text(stmt, 9); txt != nil {
			r.flag = C.GoString(txt)
		}
		rows = append(rows, r)
	}
	C.sqlite3_finalize(stmt)
	if len(rows) == 0 {
		return nil, nil
	}
	topPath := ""
	{
		var mstmt *C.sqlite3_stmt
		cm := C.CString("SELECT value FROM metadata WHERE key='top_dir_path'")
		rc := C.sqlite3_prepare_v2(s.db, cm, -1, &mstmt, nil)
		C.free(unsafe.Pointer(cm))
		if rc == C.SQLITE_OK {
			if C.sqlite3_step(mstmt) == C.SQLITE_ROW {
				if txt := C.gdu_column_text(mstmt, 0); txt != nil {
					topPath = C.GoString(txt)
				}
			}
			C.sqlite3_finalize(mstmt)
		}
	}

	nodes := make(map[int64]*Node, len(rows))
	var root *Node
	for _, r := range rows {
		n := &Node{
			Name: r.name, IsDir: r.isDir, DBID: r.id, Mli: r.mli,
			Mtime: time.Unix(r.mtime, 0), OwnMtime: time.Unix(r.mtime, 0),
		}
		if len(r.flag) > 0 {
			n.Flag = r.flag[0]
		} else {
			n.Flag = ' '
		}
		if r.isDir {
			n.TotalSize = r.size
			n.TotalUsage = r.usage
			n.OwnSize = 4096
			n.OwnUsage = 4096
			if r.count > 0 {
				n.ItemCount = int(r.count) - 1
			}
		} else {
			n.OwnSize = r.size
			n.OwnUsage = r.usage
			n.TotalSize = r.size
			n.TotalUsage = r.usage
			n.ItemCount = 1
			n.NotReg = n.Flag == '@'
			n.IsHardlink = r.mli != 0 || n.Flag == 'H'
		}
		nodes[r.id] = n
		if !r.hasParent && root == nil {
			root = n
		}
	}
	for _, r := range rows {
		n := nodes[r.id]
		if r.hasParent {
			if parent, ok := nodes[r.parentID]; ok {
				n.Parent = parent
				parent.Children = append(parent.Children, n)
			}
		}
	}
	if root != nil {
		if topPath != "" {
			root.Name = topPath
			root.Path = topPath
		} else {
			root.Path = root.Name
		}
		var setPaths func(n *Node)
		setPaths = func(n *Node) {
			for _, c := range n.Children {
				c.Path = filepath.Join(n.Path, c.Name)
				setPaths(c)
			}
		}
		setPaths(root)
	}
	return root, nil
}
