package app

import (
	"bufio"
	"fmt"
	"os"
	"strings"
	"syscall"
	"unsafe"
)

type termState struct {
	fd      int
	old     syscall.Termios
	restored bool
}

func makeRaw(fd int) (*termState, error) {
	var old syscall.Termios
	if _, _, errno := syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), uintptr(0x5401), uintptr(unsafe.Pointer(&old)), 0, 0, 0); errno != 0 {
		return nil, errno
	}
	raw := old
	raw.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP | syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
	raw.Oflag &^= syscall.OPOST
	raw.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
	raw.Cflag &^= syscall.CSIZE | syscall.PARENB
	raw.Cflag |= syscall.CS8
	raw.Cc[syscall.VMIN] = 1
	raw.Cc[syscall.VTIME] = 0
	if _, _, errno := syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), uintptr(0x5402), uintptr(unsafe.Pointer(&raw)), 0, 0, 0); errno != 0 {
		return nil, errno
	}
	return &termState{fd: fd, old: old}, nil
}

func (t *termState) restore() {
	if t.restored {
		return
	}
	t.restored = true
	syscall.Syscall6(syscall.SYS_IOCTL, uintptr(t.fd), uintptr(0x5402), uintptr(unsafe.Pointer(&t.old)), 0, 0, 0)
}

type winsize struct {
	rows, cols, xpix, ypix uint16
}

func getWinSize(fd uintptr) (int, int) {
	var ws winsize
	syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)))
	if ws.cols == 0 {
		return 80, 24
	}
	return int(ws.cols), int(ws.rows)
}

// Very small ANSI screen buffer.
type screenCell struct {
	ch    rune
	style style
}

type style struct {
	fg    int // -1 default, 0-255 ANSI 256, or 1<<24|rgb
	bg    int
	bold  bool
	rev   bool
}

var defaultStyle = style{fg: -1, bg: -1}

type screenBuf struct {
	w, h  int
	cells []screenCell
	out   *bufio.Writer
}

func newScreenBuf(out *os.File) *screenBuf {
	w, h := getWinSize(out.Fd())
	sb := &screenBuf{w: w, h: h, out: bufio.NewWriter(out)}
	sb.cells = make([]screenCell, w*h)
	sb.clear()
	return sb
}

func (s *screenBuf) clear() {
	for i := range s.cells {
		s.cells[i] = screenCell{ch: ' ', style: defaultStyle}
	}
}

func (s *screenBuf) resize() {
	w, h := getWinSize(os.Stdout.Fd())
	if w != s.w || h != s.h {
		s.w, s.h = w, h
		s.cells = make([]screenCell, w*h)
	}
	s.clear()
}

func runeWidth(r rune) int {
	if r == 0 {
		return 0
	}
	if r < 128 {
		return 1
	}
	// Rough wide-char handling: most symbols used here are width 1.
	return 1
}

func (s *screenBuf) write(x, y int, text string, st style) {
	if y < 0 || y >= s.h {
		return
	}
	for _, r := range text {
		if x >= s.w {
			break
		}
		if x >= 0 {
			s.cells[y*s.w+x] = screenCell{ch: r, style: st}
		}
		x += runeWidth(r)
	}
}

func styleSeq(st style) string {
	codes := []string{"0"}
	if st.bold {
		codes = append(codes, "1")
	}
	if st.rev {
		codes = append(codes, "7")
	}
	if st.fg >= 0 {
		if st.fg >= (1 << 24) {
			rgb := st.fg & 0xFFFFFF
			codes = append(codes, fmt.Sprintf("38;2;%d;%d;%d", rgb>>16&0xFF, rgb>>8&0xFF, rgb&0xFF))
		} else if st.fg < 8 {
			codes = append(codes, fmt.Sprintf("%d", 30+st.fg))
		} else if st.fg < 16 {
			codes = append(codes, fmt.Sprintf("%d", 90+st.fg-8))
		} else {
			codes = append(codes, fmt.Sprintf("38;5;%d", st.fg))
		}
	}
	if st.bg >= 0 {
		if st.bg >= (1 << 24) {
			rgb := st.bg & 0xFFFFFF
			codes = append(codes, fmt.Sprintf("48;2;%d;%d;%d", rgb>>16&0xFF, rgb>>8&0xFF, rgb&0xFF))
		} else if st.bg < 8 {
			codes = append(codes, fmt.Sprintf("%d", 40+st.bg))
		} else if st.bg < 16 {
			codes = append(codes, fmt.Sprintf("%d", 100+st.bg-8))
		} else {
			codes = append(codes, fmt.Sprintf("48;5;%d", st.bg))
		}
	}
	return "\x1b[" + strings.Join(codes, ";") + "m"
}

func (s *screenBuf) flush() {
	s.out.WriteString("\x1b[H")
	cur := style{fg: -2, bg: -2}
	for y := 0; y < s.h; y++ {
		if y > 0 {
			s.out.WriteString("\r\n")
		}
		// trim trailing spaces with default style to keep frame smaller
		rowEnd := s.w
		_ = rowEnd
		for x := 0; x < s.w; x++ {
			cell := s.cells[y*s.w+x]
			if cell.style != cur {
				s.out.WriteString(styleSeq(cell.style))
				cur = cell.style
			}
			s.out.WriteRune(cell.ch)
		}
	}
	s.out.WriteString("\x1b[0m")
	s.out.Flush()
}

// Key events
type keyEvent struct {
	r      rune
	special string // up down left right enter esc pgup pgdn home end delete backspace tab ctrlc mouse
	mouseX int
	mouseY int
	mouseButton int
	mouseRelease bool
}

func readKey(r *bufio.Reader) (keyEvent, error) {
	b, err := r.ReadByte()
	if err != nil {
		return keyEvent{}, err
	}
	switch b {
	case 3:
		return keyEvent{special: "ctrlc"}, nil
	case '\r', '\n':
		return keyEvent{special: "enter"}, nil
	case 127, 8:
		return keyEvent{special: "backspace"}, nil
	case '\t':
		return keyEvent{special: "tab"}, nil
	case 27:
		// Escape sequence, try to read more if available.
		peek, err := r.Peek(1)
		if err != nil || len(peek) == 0 {
			return keyEvent{special: "esc"}, nil
		}
		if peek[0] != '[' && peek[0] != 'O' {
			return keyEvent{special: "esc"}, nil
		}
		r.ReadByte() // [ or O
		// mouse SGR: [<b;x;yM/m
		if peek2, _ := r.Peek(1); len(peek2) > 0 && peek2[0] == '<' {
			r.ReadByte()
			var params []int
			cur := 0
			has := false
			for {
				c, err := r.ReadByte()
				if err != nil { break }
				if c >= '0' && c <= '9' { cur = cur*10 + int(c-'0'); has = true; continue }
				if c == ';' { params = append(params, cur); cur = 0; has = false; continue }
				if has || true { params = append(params, cur) }
				ev := keyEvent{special: "mouse", mouseRelease: c == 'm'}
				if len(params) >= 3 { ev.mouseButton = params[0]; ev.mouseX = params[1]-1; ev.mouseY = params[2]-1 }
				return ev, nil
			}
			return keyEvent{special: "esc"}, nil
		}
		// Read final byte(s)
		code := ""
		for {
			c, err := r.ReadByte()
			if err != nil {
				break
			}
			code += string(c)
			if (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || c == '~' {
				break
			}
			if len(code) > 10 { break }
		}
		switch code {
		case "A":
			return keyEvent{special: "up"}, nil
		case "B":
			return keyEvent{special: "down"}, nil
		case "C":
			return keyEvent{special: "right"}, nil
		case "D":
			return keyEvent{special: "left"}, nil
		case "H":
			return keyEvent{special: "home"}, nil
		case "F":
			return keyEvent{special: "end"}, nil
		case "5~":
			return keyEvent{special: "pgup"}, nil
		case "6~":
			return keyEvent{special: "pgdn"}, nil
		case "3~":
			return keyEvent{special: "delete"}, nil
		case "Z":
			return keyEvent{special: "shift-tab"}, nil
		}
		return keyEvent{special: "esc"}, nil
	default:
		if b < 128 {
			return keyEvent{r: rune(b)}, nil
		}
		// UTF-8 sequence: reconstruct
		buf := []byte{b}
		n := 1
		if b >= 0xF0 { n = 4 } else if b >= 0xE0 { n = 3 } else if b >= 0xC0 { n = 2 }
		for i := 1; i < n; i++ {
			c, err := r.ReadByte()
			if err != nil { break }
			buf = append(buf, c)
		}
		rn := []rune(string(buf))
		if len(rn) > 0 {
			return keyEvent{r: rn[0]}, nil
		}
		return keyEvent{}, nil
	}
}
