func newTermUI(root *Node, flags *Flags, absPath string) *termUI {
	ui := &termUI{
		root: root, current: root, flags: flags, absPath: absPath,
		sortBy: "size",
		showApparent: flags.ShowApparentSize,
		showCount: flags.ShowItemCount,
