		relative: flags.ShowRelativeSize,
	}
	if flags.Sorting.By != "" {
		switch flags.Sorting.By {
		case "name", "size", "itemCount", "mtime":
			ui.sortBy = flags.Sorting.By
		}
	}
	ui.sortAsc = flags.Sorting.Order == "asc"
	ui.refreshItems()
	return ui
}

func (ui *termUI) refreshItems() {
	children := make([]*Node, len(ui.current.Children))
	copy(children, ui.current.Children)
	// filter out ignored nodes for totals purposes is handled in drawing;
	// items stay in the list.
	sort.SliceStable(children, func(i, j int) bool {
		a, b := children[i], children[j]
		var cmp int
		switch ui.sortBy {
		case "name":
			cmp = compareNatural(a.Name, b.Name)
			if ui.sortAsc { return cmp < 0 }
			return cmp > 0
		case "itemCount":
			if a.ItemCount != b.ItemCount {
				if ui.sortAsc { return a.ItemCount < b.ItemCount }
				return a.ItemCount > b.ItemCount
			}
			cmp = compareNatural(a.Name, b.Name)
			if ui.sortAsc { return cmp < 0 }
			return cmp > 0
		case "mtime":
			if !a.Mtime.Equal(b.Mtime) {
				if ui.sortAsc { return a.Mtime.Before(b.Mtime) }
				return a.Mtime.After(b.Mtime)
			}
			cmp = compareNatural(a.Name, b.Name)
			if ui.sortAsc { return cmp < 0 }
			return cmp > 0
		default: // size
			av := a.DisplaySize(ui.showApparent)
			bv := b.DisplaySize(ui.showApparent)
			if av != bv {
				if ui.sortAsc { return av < bv }
				return av > bv
			}
			cmp = compareNatural(a.Name, b.Name)
			if ui.sortAsc { return cmp < 0 }
			return cmp > 0
		}
	})
	ui.hasParentRow = ui.current.Parent != nil
	ui.items = nil
	if ui.hasParentRow {
		ui.items = append(ui.items, nil)
	}
	ui.items = append(ui.items, children...)
	if ui.cursor >= len(ui.items) {
		ui.cursor = len(ui.items) - 1
	}
	if ui.cursor < 0 {
		ui.cursor = 0
	}
