func barString(value, total int64, useUnicode bool) string {
	width := 10
	if total <= 0 || value <= 0 {
		if useUnicode {
			return strings.Repeat(" ", width)
		}
		return strings.Repeat(" ", width)
	}
	// eighths, floored
	eighths := int(float64(value) / float64(total) * float64(width) * 8)
	if eighths > width*8 {
		eighths = width * 8
	}
	full := eighths / 8
	rem := eighths % 8
	if !useUnicode {
		// old-style ascii bar
		n := full
		if rem > 0 {
			n++
		}
		return strings.Repeat("#", n) + strings.Repeat(" ", width-n)
	}
	partials := []rune{' ', '▏', '▎', '▍', '▌', '▋', '▊', '▉'}
	var b strings.Builder
	b.WriteString(strings.Repeat("█", full))
	used := full
	if rem > 0 && full < width {
		b.WriteRune(partials[rem])
		used++
	}
	if used < width {
		b.WriteString(strings.Repeat(" ", width-used))
	}
	return b.String()
}

func hexToColor(s string, fallback int) int {
	s = strings.TrimSpace(s)
	if strings.HasPrefix(s, "#") && len(s) == 7 {
		var v int
		if _, err := fmt.Sscanf(s, "#%06x", &v); err == nil {
			return (1 << 24) | v
		}
	}
	named := map[string]int{
		"black": 0, "red": 1, "green": 2, "yellow": 3, "blue": 4, "magenta": 5, "cyan": 6, "white": 7,
		"default": -1, "": fallback,
	}
	if v, ok := named[strings.ToLower(s)]; ok {
		return v
	}
	// numeric palette index
	var v int
	if _, err := fmt.Sscanf(s, "%d", &v); err == nil {
		return v
	}
	return fallback
}

func (ui *termUI) run() error {
	if len(ui.current.Children) == 0 && ui.current.Parent == nil {
		// still show UI
	}
	fd := int(os.Stdin.Fd())
	state, err := makeRaw(fd)
	if err != nil {
		// Not a TTY: print listing as fallback.
		printListing(os.Stdout, ui.current, ui.flags)
		return nil
	}
	defer state.restore()
	out := os.Stdout
	out.WriteString("\x1b[?1049h\x1b[?25l")
	defer out.WriteString("\x1b[?25h\x1b[?1049l")
	if ui.flags.Mouse {
		out.WriteString("\x1b[?1000h\x1b[?1002h\x1b[?1006h")
		defer out.WriteString("\x1b[?1006l\x1b[?1002l\x1b[?1000l")
	}
	sb := newScreenBuf(out)
	input := bufio.NewReader(os.Stdin)
	for {
		sb.resize()
		ui.draw(sb)
		sb.flush()
		ev, err := readKey(input)
		if err != nil {
			break
		}
		if quit := ui.handleKey(ev, sb, input); quit {
			break
		}
	}
	if ui.quitPath {
		state.restore()
		out.WriteString("\x1b[?25h\x1b[?1049l")
		fmt.Fprintln(out, ui.current.fullPath())
		// prevent double restore output in defer from reprinting alt screen exit after path
		// (defer order: this function returns after, defers run -- acceptable minor diff)
	}
	return nil
}

func (ui *termUI) handleKey(ev keyEvent, sb *screenBuf, input *bufio.Reader) bool {
	// Implemented in ui_keys.go via handleKeyImpl if present.
	return ui.handleKeyImpl(ev, sb, input)
}
