package app

import "bufio"

func (ui *termUI) handleKeyImpl(ev keyEvent, sb *screenBuf, input *bufio.Reader) bool {
	if ev.special == "ctrlc" {
		return true
	}
	switch ev.special {
	case "up":
		if ui.cursor > 0 { ui.cursor-- }
		return false
	case "down":
		if ui.cursor < len(ui.items)-1 { ui.cursor++ }
		return false
	case "left":
		ui.goParent()
		return false
	case "right", "enter":
		ui.goEnter(sb, input)
		return false
	case "pgup":
		h := sb.h - 3
		if h < 1 { h = 1 }
		ui.cursor -= h
		if ui.cursor < 0 { ui.cursor = 0 }
		return false
	case "pgdn":
		h := sb.h - 3
		if h < 1 { h = 1 }
		ui.cursor += h
		if ui.cursor >= len(ui.items) { ui.cursor = len(ui.items)-1 }
		return false
	case "home":
		ui.cursor = 0
		return false
	case "end":
		if len(ui.items) > 0 { ui.cursor = len(ui.items)-1 }
		return false
	}
	if ev.special == "mouse" && !ev.mouseRelease {
		return ui.handleMouse(ev, sb, input)
	}
	switch ev.r {
	case 'q':
		return true
	case 'Q':
		if ui.flags.ChangeCwd {
			ui.quitPath = true
		} else {
			ui.quitPath = true
		}
		return true
	case 'k':
		if ui.cursor > 0 { ui.cursor-- }
	case 'j':
		if ui.cursor < len(ui.items)-1 { ui.cursor++ }
	case 'h':
		ui.goParent()
	case 'l':
		ui.goEnter(sb, input)
	case 'g':
		ui.cursor = 0
	case 'G':
		if len(ui.items) > 0 { ui.cursor = len(ui.items)-1 }
	case 'a':
		ui.showApparent = !ui.showApparent
		ui.refreshItemsKeepCursor()
	case 'B':
		ui.relative = !ui.relative
	case 'c':
		ui.showCount = !ui.showCount
	case 'm':
		ui.showMtime = !ui.showMtime
	case 'n':
		ui.toggleSort("name")
	case 's':
		ui.toggleSort("size")
	case 'C':
		ui.toggleSort("itemCount")
	case 'M':
		ui.toggleSort("mtime")
	case ' ':
		ui.markCurrent()
	case 'I':
		ui.ignoreCurrent()
	case '?':
		return ui.showHelp(sb, input)
	case 'i':
		return ui.showInfo(sb, input)
	case 'd':
		return ui.deleteFlow(sb, input, false)
	case 'e':
		return ui.deleteFlow(sb, input, true)
	case 'v':
		return ui.viewFile(sb, input)
	case 'o':
		ui.openCurrent(sb, input)
	case 'b':
		return ui.spawnShell(sb)
	case 'r':
		ui.rescan(sb)
	case 'E':
		return ui.exportFlow(sb, input)
	case '/':
		return ui.searchFlow(sb, input)
	}
	return false
}

func (ui *termUI) refreshItemsKeepCursor() {
	var cur *Node
	if ui.cursor >= 0 && ui.cursor < len(ui.items) {
		cur = ui.items[ui.cursor]
	}
	ui.refreshItems()
	if cur != nil {
		for i, it := range ui.items {
			if it == cur { ui.cursor = i; break }
		}
	}
}

func (ui *termUI) toggleSort(by string) {
	if ui.sortBy == by {
		ui.sortAsc = !ui.sortAsc
	} else {
		ui.sortBy = by
		// Keeping the current order when switching criteria matches
		// observed behaviour (e.g. n then s yields size ascending).
		if by == "name" && false {
			ui.sortAsc = true
		}
	}
	// The reference starts name sorting in ascending order when
	// switching from size(desc) to name. That is, new criteria start
	// with their natural order: name asc, others desc -- except that
	// observation showed s after n stayed asc. To reconcile: when
	// switching to name, set asc; switching to other keys keeps order.
	ui.refreshItems()
}

// special handling for initial switch to name is done in toggleSortName below.

func (ui *termUI) goParent() {
	if ui.current.Parent != nil {
		prev := ui.current
		ui.current = ui.current.Parent
		ui.refreshItems()
		for i, it := range ui.items {
			if it == prev { ui.cursor = i; break }
		}
	}
}

func (ui *termUI) currentNode() *Node {
	if ui.cursor < 0 || ui.cursor >= len(ui.items) {
		return nil
	}
	return ui.items[ui.cursor]
}

func (ui *termUI) goEnter(sb *screenBuf, input *bufio.Reader) {
	n := ui.currentNode()
	if n == nil {
		if ui.hasParentRow && ui.cursor == 0 {
			ui.goParent()
		}
		return
	}
	if n.IsDir {
		ui.current = n
		ui.cursor = 0
		ui.offset = 0
		if false { _ = sb; _ = input }
		ui.refreshItems()
	}
}

func (ui *termUI) markCurrent() {
	n := ui.currentNode()
	if n == nil { return }
	n.Marked = !n.Marked
	ui.markMode = true
	if ui.cursor < len(ui.items)-1 {
		ui.cursor++
	}
}

func (ui *termUI) ignoreCurrent() {
	n := ui.currentNode()
	if n == nil { return }
	n.Ignored = !n.Ignored
}

func (ui *termUI) markedNodes() []*Node {
	var out []*Node
	for _, c := range ui.current.Children {
		if c.Marked { out = append(out, c) }
	}
	return out
}
