	ui.items = nil
	if ui.hasParentRow {
		ui.items = append(ui.items, nil)
	}
	ui.items = append(ui.items, children...)
	if ui.cursor >= len(ui.items) {
		ui.cursor = len(ui.items) - 1
	}
	if ui.cursor < 0 {
		ui.cursor = 0
	}
}

func (ui *termUI) footerTotals() (usage, apparent int64, items int) {
