func (ui *termUI) handleKeyImpl(ev keyEvent, sb *screenBuf, input *bufio.Reader) bool {
	if ev.special == "ctrlc" {
		return true
	}
	switch ev.special {
	case "up":
		if ui.cursor > 0 { ui.cursor-- }
		return false
	case "down":
		if ui.cursor < len(ui.items)-1 { ui.cursor++ }
		return false
	case "left":
		ui.goParent()
		return false
	case "right", "enter":
		ui.goEnter(sb, input)
		return false
	case "pgup":
		h := sb.h - 3
		if h < 1 { h = 1 }
		ui.cursor -= h
		if ui.cursor < 0 { ui.cursor = 0 }
		return false
	case "pgdn":
		h := sb.h - 3
		if h < 1 { h = 1 }
		ui.cursor += h
		if ui.cursor >= len(ui.items) { ui.cursor = len(ui.items)-1 }
		return false
	case "home":
		ui.cursor = 0
		return false
	case "end":
		if len(ui.items) > 0 { ui.cursor = len(ui.items)-1 }
		return false
	}
	if ev.special == "mouse" && !ev.mouseRelease {
		return ui.handleMouse(ev, sb, input)
	}
	switch ev.r {
	case 'q':
		return true
	case 'Q':
		if ui.flags.ChangeCwd {
			ui.quitPath = true
		} else {
