		ui.goParent()
	case 'l':
		ui.goEnter(sb, input)
	case 'g':
		ui.cursor = 0
	case 'G':
		if len(ui.items) > 0 { ui.cursor = len(ui.items)-1 }
	case 'a':
		ui.showApparent = !ui.showApparent
		ui.refreshItemsKeepCursor()
	case 'B':
		ui.relative = !ui.relative
	case 'c':
		ui.showCount = !ui.showCount
	case 'm':
		ui.showMtime = !ui.showMtime
	case 'n':
		ui.toggleSort("name")
	case 's':
		ui.toggleSort("size")
	case 'C':
		ui.toggleSort("itemCount")
	case 'M':
		ui.toggleSort("mtime")
	case ' ':
		ui.markCurrent()
	case 'I':
		ui.ignoreCurrent()
	case '?':
		return ui.showHelp(sb, input)
	case 'i':
		return ui.showInfo(sb, input)
	case 'd':
		return ui.deleteFlow(sb, input, false)
	case 'e':
		return ui.deleteFlow(sb, input, true)
	case 'v':
		return ui.viewFile(sb, input)
	case 'o':
		ui.openCurrent(sb, input)
	case 'b':
		return ui.spawnShell(sb)
	case 'r':
