		return ui.searchFlow(sb, input)
	}
	return false
}

func (ui *termUI) refreshItemsKeepCursor() {
	var cur *Node
	if ui.cursor >= 0 && ui.cursor < len(ui.items) {
		cur = ui.items[ui.cursor]
	}
	ui.refreshItems()
	if cur != nil {
		for i, it := range ui.items {
			if it == cur { ui.cursor = i; break }
		}
	}
}

func (ui *termUI) toggleSort(by string) {
	if ui.sortBy == by {
		ui.sortAsc = !ui.sortAsc
	} else {
		ui.sortBy = by
		// Keeping the current order when switching criteria matches
