	if ui.current.Parent != nil {
		prev := ui.current
		ui.current = ui.current.Parent
		ui.refreshItems()
		for i, it := range ui.items {
			if it == prev { ui.cursor = i; break }
		}
	}
}

func (ui *termUI) currentNode() *Node {
	if ui.cursor < 0 || ui.cursor >= len(ui.items) {
		return nil
	}
	return ui.items[ui.cursor]
}

func (ui *termUI) goEnter(sb *screenBuf, input *bufio.Reader) {
	n := ui.currentNode()
	if n == nil {
		if ui.hasParentRow && ui.cursor == 0 {
			ui.goParent()
		}
		return
	}
	if n.IsDir {
		ui.current = n
		ui.cursor = 0
		ui.offset = 0
		if false { _ = sb; _ = input }
		ui.refreshItems()
	}
}

func (ui *termUI) markCurrent() {
	n := ui.currentNode()
	if n == nil { return }
	n.Marked = !n.Marked
	ui.markMode = true
	if ui.cursor < len(ui.items)-1 {
		ui.cursor++
	}
}

func (ui *termUI) ignoreCurrent() {
	n := ui.currentNode()
	if n == nil { return }
	n.Ignored = !n.Ignored
}

func (ui *termUI) markedNodes() []*Node {
	var out []*Node
	for _, c := range ui.current.Children {
		if c.Marked { out = append(out, c) }
	}
	return out
}
