func (ui *termUI) goEnter(sb *screenBuf, input *bufio.Reader) {
	n := ui.currentNode()
	if n == nil {
		if ui.hasParentRow && ui.cursor == 0 {
			ui.goParent()
		}
		return
	}
	if n.IsDir {
