package app

import (
	"bufio"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
)

// Modal helpers live in ui_modals.go; actions needing the scanner or OS
// are kept here.

func (ui *termUI) rescan(sb *screenBuf) {
	// Re-scan only the current directory subtree if it is a real path
	// and the root was scanned from disk. For imported analyses, do nothing.
	path := ui.current.fullPath()
	info, err := os.Stat(path)
	if err != nil || !info.IsDir() {
		return
	}
	// Build a scanner with current flag settings and fresh seen-map.
	// Ignore-dirs / patterns from the original run are not retained in
	// this simplified rescan beyond flags.
	scan := newScanner(ui.flags, nil, nil, nil, nil)
	scan.sequential = ui.flags.SequentialScanning
	newNode := scan.analyze(path)
	// Splice newNode into parent (or replace root).
	if ui.current.Parent == nil {
		newNode.Name = ui.current.Name
		newNode.Path = ui.current.Path
		ui.root = newNode
		ui.current = newNode
	} else {
		parent := ui.current.Parent
		newNode.Name = ui.current.Name
		newNode.Path = ui.current.Path
		newNode.Parent = parent
		for i, c := range parent.Children {
			if c == ui.current {
				parent.Children[i] = newNode
				break
			}
		}
		ui.current = newNode
		// Recompute ancestor totals/mtimes.
		recomputeAncestors(parent)
	}
	ui.cursor = 0
	ui.offset = 0
	ui.refreshItems()
}

func recomputeAncestors(n *Node) {
	for cur := n; cur != nil; cur = cur.Parent {
		latest := cur.OwnMtime
		totalSize := int64(4096)
		totalUsage := int64(4096)
		count := 0
		for _, child := range cur.Children {
			if child.Mtime.After(latest) { latest = child.Mtime }
			count += child.ItemCount
			if child.IsDir {
				totalSize += child.TotalSize
				totalUsage += child.TotalUsage
			} else if !child.AlreadyCounted {
				totalSize += child.OwnSize
				totalUsage += child.OwnUsage
			}
		}
		cur.Mtime = latest
		cur.TotalSize = totalSize
		cur.TotalUsage = totalUsage
		cur.ItemCount = count
	}
}

func (ui *termUI) spawnShell(sb *screenBuf) bool {
	if ui.flags.NoSpawnShell {
		return false
	}
	shell := os.Getenv("SHELL")
	if shell == "" {
		shell = "/bin/sh"
	}
	// The full implementation suspends the TUI; our raw terminal
	// version restores the terminal in a similar way in ui run loop.
	// Here we signal the caller through a dedicated mechanism:
	ui.pendingShell = shell
	return false
}

func (ui *termUI) openCurrent(sb *screenBuf, input *bufio.Reader) {
	n := ui.currentNode()
	if n == nil { return }
	path := n.fullPath()
	cmd := exec.Command("xdg-open", path)
	_ = cmd.Start()
}

func (ui *termUI) handleMouse(ev keyEvent, sb *screenBuf, input *bufio.Reader) bool {
	listStart := 2
	if ev.mouseButton == 64 { // wheel up
		if ui.cursor > 0 { ui.cursor-- }
		return false
	}
	if ev.mouseButton == 65 { // wheel down
		if ui.cursor < len(ui.items)-1 { ui.cursor++ }
		return false
	}
	if ev.mouseY >= listStart {
		idx := ui.offset + (ev.mouseY - listStart)
		if idx >= 0 && idx < len(ui.items) {
			if idx == ui.cursor {
				ui.goEnter(sb, input)
			} else {
				ui.cursor = idx
			}
		}
	}
	return false
}

func sortedHardlinks(root *Node, mli uint64) []string {
	var paths []string
	var walk func(n *Node)
	walk = func(n *Node) {
		if !n.IsDir && n.Mli == mli && mli != 0 {
			paths = append(paths, n.fullPath())
		}
		for _, c := range n.Children { walk(c) }
	}
	walk(root)
	sort.Strings(paths)
	return paths
}

func removeNodeFromParent(n *Node) {
	if n.Parent == nil { return }
	parent := n.Parent
	for i, c := range parent.Children {
		if c == n {
			parent.Children = append(parent.Children[:i], parent.Children[i+1:]...)
			break
		}
	}
	recomputeAncestors(parent)
}

func deletePath(path string) error {
	info, err := os.Lstat(path)
	if err != nil { return err }
	if info.IsDir() && info.Mode()&os.ModeSymlink == 0 {
		return os.RemoveAll(path)
	}
	return os.Remove(path)
}

func emptyPath(path string) error {
	info, err := os.Lstat(path)
	if err != nil { return err }
	if !info.IsDir() {
		// Empty a file: truncate (reference says "Empty file or directory").
		return os.Truncate(path, 0)
	}
	entries, err := os.ReadDir(path)
	if err != nil { return err }
	for _, e := range entries {
		if err := os.RemoveAll(filepath.Join(path, e.Name())); err != nil {
			return err
		}
	}
	return nil
}

var _ = strings.TrimSpace
var _ = fmt.Sprintf
