func (ui *termUI) confirmModal(sb *screenBuf, input *bufio.Reader, question string) int {
	// returns 0=no,1=yes,2=dontask
	sel := 0
	options := []string{"no", "yes", "don't ask me again"}
	for {
		sb.resize()
		ui.draw(sb)
		w, h := 43, 7
		x := (sb.w - w) / 2
		y := sb.h - 11
		if y < 2 { y = 2 }
		ui.drawBox(sb, x, y, w, h, "", true)
		bg := style{fg: -1, bg: 0}
		lines := wrapText(question, w-4)
		for i, l := range lines {
			sb.write(x+2, y+2+i, padRight(l, w-4), bg)
		}
		// options row centred-ish: "no     yes     don't ask me again"
		optY := y + 5
		ox := x + 4
		for i, opt := range options {
			st := bg
			if i == sel {
				st = style{fg: 15, bg: 2, bold: true}
			}
			sb.write(ox, optY, opt, st)
			ox += len(opt) + 5
		}
		sb.flush()
		ev, err := readKey(input)
		if err != nil { return 0 }
		if ev.special == "ctrlc" || ev.special == "esc" || ev.r == 'q' { return 0 }
		if ev.special == "enter" { return sel }
		if ev.special == "left" || ev.r == 'h' || ev.special == "tab" {
			// tab moves right in reference probably; left moves left
			if ev.special == "tab" {
				sel = (sel + 1) % len(options)
			} else if sel > 0 { sel-- }
		}
		if ev.special == "right" || ev.r == 'l' {
			if sel < len(options)-1 { sel++ }
		}
		if ev.special == "mouse" && !ev.mouseRelease && ev.mouseY == optY {
			ox2 := x + 4
			for i, opt := range options {
				if ev.mouseX >= ox2 && ev.mouseX < ox2+len(opt) { return i }
				ox2 += len(opt) + 5
			}
		}
	}
}

func wrapText(s string, w int) []string {
	words := strings.Fields(s)
	var lines []string
	cur := ""
	for _, word := range words {
		if cur == "" { cur = word; continue }
		if len(cur)+1+len(word) > w {
			lines = append(lines, cur)
			cur = word
		} else {
			cur += " " + word
		}
	}
	if cur != "" { lines = append(lines, cur) }
	// centre each line as in reference confirm modal
	for i, l := range lines {
		pad := (w - len(l)) / 2
		if pad > 0 { lines[i] = strings.Repeat(" ", pad) + l }
	}
	return lines
}

func (ui *termUI) deleteFlow(sb *screenBuf, input *bufio.Reader, empty bool) bool {
	if ui.flags.NoDelete { return false }
	targets := ui.markedNodes()
	if len(targets) == 0 {
		n := ui.currentNode()
		if n == nil { return false }
		targets = []*Node{n}
	}
	var question string
	verb := "delete"
	if empty { verb = "empty" }
	if len(targets) == 1 {
		kind := "file"
		if targets[0].IsDir { kind = "directory" }
		if empty {
			question = fmt.Sprintf("Are you sure you want to empty %s?", targets[0].Name)
			_ = kind
		} else {
			question = fmt.Sprintf("Are you sure you want to delete %s?", targets[0].Name)
		}
	} else {
		question = fmt.Sprintf("Are you sure you want to %s %d items?", verb, len(targets))
	}
	choice := 1
	if !ui.dontAskDelete {
		choice = ui.confirmModal(sb, input, question)
		if choice == 0 { return false }
		if choice == 2 { ui.dontAskDelete = true }
	}
	_ = choice
	for _, n := range targets {
		p := n.fullPath()
		var err error
		if empty {
			err = emptyPath(p)
			if err == nil {
				if n.IsDir {
					n.Children = nil
					n.Flag = 'e'
					recomputeAncestors(n)
				} else {
					n.OwnSize = 0
					n.OwnUsage = 0
				}
			}
		} else {
			err = deletePath(p)
			if err == nil {
				removeNodeFromParent(n)
			}
		}
		if err != nil {
			logInfo("%s", err.Error())
		}
		n.Marked = false
	}
	if len(ui.markedNodes()) == 0 {
		// keep attempted: keep mark mode if reference does; keep simple
	}
	ui.refreshItems()
	return false
}

func (ui *termUI) viewFile(sb *screenBuf, input *bufio.Reader) bool {
	n := ui.currentNode()
	if n == nil || n.IsDir { return false }
	data, err := os.ReadFile(n.fullPath())
	content := ""
	if err != nil {
		content = err.Error()
	} else {
		content = string(data)
	}
	lines := strings.Split(strings.ReplaceAll(content, "\r\n", "\n"), "\n")
	offset := 0
	for {
		sb.resize()
		ui.draw(sb)
		w, h := sb.w, sb.h-2
		if h < 3 { h = 3 }
		y := 1
		ui.drawBox(sb, 0, y, w, h, n.Name, false)
		bg := style{fg: -1, bg: 0}
		for i := 0; i < h-2; i++ {
			idx := offset + i
			if idx >= len(lines) { break }
			sb.write(1, y+1+i, padRight(lines[idx], w-2), bg)
		}
		sb.flush()
		ev, err := readKey(input)
		if err != nil { return true }
		if ev.r == 'q' || ev.r == 'Q' || ev.special == "esc" || ev.r == 'v' { return false }
		if ev.special == "ctrlc" { return false }
		if ev.r == 'j' || ev.special == "down" { offset++ }
		if ev.r == 'k' || ev.special == "up" { if offset > 0 { offset-- } }
		if ev.special == "pgdn" { offset += h }
		if ev.special == "pgup" { offset -= h; if offset < 0 { offset = 0 } }
		if ev.r == 'g' { offset = 0 }
		if ev.r == 'G' { offset = len(lines) }
		if offset > len(lines) { offset = len(lines) }
	}
}

func (ui *termUI) textInput(sb *screenBuf, input *bufio.Reader, title, initial string) (string, bool) {
	text := initial
	for {
		sb.resize()
		ui.draw(sb)
		w := sb.w
		if w > 70 { w = 70 }
		h := 5
		x := (sb.w - w) / 2
		y := (sb.h - h) / 2
		ui.drawBox(sb, x, y, w, h, title, true)
		bg := style{fg: -1, bg: 0}
		sb.write(x+2, y+2, padRight(text, w-4), bg)
		sb.flush()
		ev, err := readKey(input)
		if err != nil { return "", false }
		if ev.special == "enter" { return text, true }
		if ev.special == "esc" || ev.special == "ctrlc" { return "", false }
		if ev.special == "backspace" {
			r := []rune(text)
			if len(r) > 0 { text = string(r[:len(r)-1]) }
			continue
		}
		if ev.r != 0 {
			text += string(ev.r)
		}
	}
}

func (ui *termUI) exportFlow(sb *screenBuf, input *bufio.Reader) bool {
	path, ok := ui.textInput(sb, input, "Export to file", "gdu-export.json")
	if !ok || strings.TrimSpace(path) == "" { return false }
	f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o600)
	if err == nil {
		defer f.Close()
		_ = exportAnalysis(f, ui.root, "")
	}
	return false
}

func (ui *termUI) searchFlow(sb *screenBuf, input *bufio.Reader) bool {
	// Live search in footer/header area: prompt on the title row.
	query := ""
	origCursor, origCurrent := ui.cursor, ui.current
	_ = origCursor
	for {
		sb.resize()
		ui.draw(sb)
		// draw search prompt over title line (row 1)
		bg := style{fg: 15, bg: 0}
		prompt := "/" + query
		sb.write(0, 1, padRight(prompt, sb.w), bg)
		sb.flush()
		ev, err := readKey(input)
		if err != nil { return true }
		if ev.special == "enter" {
			// jump to first match (already selected if found)
			return false
		}
		if ev.special == "esc" || ev.special == "ctrlc" {
			ui.current = origCurrent
			ui.refreshItems()
			return false
		}
		if ev.special == "backspace" {
			r := []rune(query)
			if len(r) > 0 { query = string(r[:len(r)-1]) }
		} else if ev.special == "down" {
			// next match
			ui.jumpToMatch(query, 1)
			continue
		} else if ev.special == "up" {
			ui.jumpToMatch(query, -1)
			continue
		} else if ev.r != 0 {
			query += string(ev.r)
		} else {
			continue
		}
		if query != "" {
			ui.jumpToFirstMatch(query)
		}
	}
}

func (ui *termUI) jumpToFirstMatch(query string) {
	for i, it := range ui.items {
		if it != nil && strings.Contains(strings.ToLower(it.Name), strings.ToLower(query)) {
			ui.cursor = i
			return
		}
	}
}
func (ui *termUI) jumpToMatch(query string, dir int) {
	if query == "" { return }
	for step := 1; step <= len(ui.items); step++ {
		idx := ui.cursor + dir*step
		if idx < 0 || idx >= len(ui.items) { return }
		it := ui.items[idx]
		if it != nil && strings.Contains(strings.ToLower(it.Name), strings.ToLower(query)) {
			ui.cursor = idx
			return
		}
	}
}

func (ui *termUI) doSpawnShell() {
	if ui.flags.NoSpawnShell { return }
	shell := os.Getenv("SHELL")
	if shell == "" { shell = "/bin/sh" }
	if ui.term != nil { ui.term.restore() }
	os.Stdout.WriteString("\x1b[?25h\x1b[?1049l")
	cmd := exec.Command(shell)
	cmd.Dir = ui.current.fullPath()
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	_ = cmd.Run()
	os.Stdout.WriteString("\x1b[?1049h\x1b[?25l")
	if st, err := makeRaw(int(os.Stdin.Fd())); err == nil {
		ui.term = st
	}
}
