func wrapText(s string, w int) []string {
	words := strings.Fields(s)
	var lines []string
	cur := ""
	for _, word := range words {
		if cur == "" { cur = word; continue }
		if len(cur)+1+len(word) > w {
			lines = append(lines, cur)
			cur = word
		} else {
			cur += " " + word
		}
	}
	if cur != "" { lines = append(lines, cur) }
	// centre each line as in reference confirm modal
	for i, l := range lines {
		pad := (w - len(l)) / 2
		if pad > 0 { lines[i] = strings.Repeat(" ", pad) + l }
	}
	return lines
}

func (ui *termUI) deleteFlow(sb *screenBuf, input *bufio.Reader, empty bool) bool {
	if ui.flags.NoDelete { return false }
	targets := ui.markedNodes()
	if len(targets) == 0 {
		n := ui.currentNode()
		if n == nil { return false }
		targets = []*Node{n}
	}
	var question string
	verb := "delete"
	if empty { verb = "empty" }
	if len(targets) == 1 {
		kind := "file"
		if targets[0].IsDir { kind = "directory" }
		if empty {
			question = fmt.Sprintf("Are you sure you want to empty %s?", targets[0].Name)
			_ = kind
		} else {
			question = fmt.Sprintf("Are you sure you want to delete %s?", targets[0].Name)
		}
	} else {
		question = fmt.Sprintf("Are you sure you want to %s %d items?", verb, len(targets))
	}
	choice := 1
	if !ui.dontAskDelete {
		choice = ui.confirmModal(sb, input, question)
		if choice == 0 { return false }
		if choice == 2 { ui.dontAskDelete = true }
	}
	_ = choice
	for _, n := range targets {
		p := n.fullPath()
		var err error
		if empty {
			err = emptyPath(p)
			if err == nil {
				if n.IsDir {
					n.Children = nil
					n.Flag = 'e'
					recomputeAncestors(n)
				} else {
					n.OwnSize = 0
					n.OwnUsage = 0
				}
			}
		} else {
			err = deletePath(p)
			if err == nil {
				removeNodeFromParent(n)
			}
		}
		if err != nil {
			logInfo("%s", err.Error())
		}
		n.Marked = false
	}
	if len(ui.markedNodes()) == 0 {
		// keep attempted: keep mark mode if reference does; keep simple
	}
	ui.refreshItems()
	return false
}

func (ui *termUI) viewFile(sb *screenBuf, input *bufio.Reader) bool {
	n := ui.currentNode()
	if n == nil || n.IsDir { return false }
	data, err := os.ReadFile(n.fullPath())
	content := ""
	if err != nil {
		content = err.Error()
	} else {
		content = string(data)
	}
	lines := strings.Split(strings.ReplaceAll(content, "\r\n", "\n"), "\n")
	offset := 0
	for {
		sb.resize()
		ui.draw(sb)
		w, h := sb.w, sb.h-2
		if h < 3 { h = 3 }
		y := 1
		ui.drawBox(sb, 0, y, w, h, n.Name, false)
		bg := style{fg: -1, bg: 0}
		for i := 0; i < h-2; i++ {
			idx := offset + i
			if idx >= len(lines) { break }
			sb.write(1, y+1+i, padRight(lines[idx], w-2), bg)
		}
		sb.flush()
		ev, err := readKey(input)
		if err != nil { return true }
		if ev.r == 'q' || ev.r == 'Q' || ev.special == "esc" || ev.r == 'v' { return false }
		if ev.special == "ctrlc" { return false }
		if ev.r == 'j' || ev.special == "down" { offset++ }
		if ev.r == 'k' || ev.special == "up" { if offset > 0 { offset-- } }
		if ev.special == "pgdn" { offset += h }
		if ev.special == "pgup" { offset -= h; if offset < 0 { offset = 0 } }
		if ev.r == 'g' { offset = 0 }
		if ev.r == 'G' { offset = len(lines) }
		if offset > len(lines) { offset = len(lines) }
	}
}

func (ui *termUI) textInput(sb *screenBuf, input *bufio.Reader, title, initial string) (string, bool) {
	text := initial
	for {
