			if len(r) > 0 { text = string(r[:len(r)-1]) }
			continue
		}
		if ev.r != 0 {
			text += string(ev.r)
		}
	}
}

func (ui *termUI) exportFlow(sb *screenBuf, input *bufio.Reader) bool {
	path, ok := ui.textInput(sb, input, "Export to file", "gdu-export.json")
	if !ok || strings.TrimSpace(path) == "" { return false }
	f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o600)
	if err == nil {
		defer f.Close()
		_ = exportAnalysis(f, ui.root, "")
	}
	return false
}

func (ui *termUI) searchFlow(sb *screenBuf, input *bufio.Reader) bool {
	// Live search in footer/header area: prompt on the title row.
	query := ""
	origCursor, origCurrent := ui.cursor, ui.current
	_ = origCursor
	for {
		sb.resize()
		ui.draw(sb)
		// draw search prompt over title line (row 1)
		bg := style{fg: 15, bg: 0}
		prompt := "/" + query
		sb.write(0, 1, padRight(prompt, sb.w), bg)
		sb.flush()
		ev, err := readKey(input)
		if err != nil { return true }
		if ev.special == "enter" {
			// jump to first match (already selected if found)
			return false
		}
		if ev.special == "esc" || ev.special == "ctrlc" {
			ui.current = origCurrent
			ui.refreshItems()
			return false
		}
		if ev.special == "backspace" {
			r := []rune(query)
			if len(r) > 0 { query = string(r[:len(r)-1]) }
		} else if ev.special == "down" {
			// next match
			ui.jumpToMatch(query, 1)
			continue
		} else if ev.special == "up" {
			ui.jumpToMatch(query, -1)
			continue
		} else if ev.r != 0 {
			query += string(ev.r)
		} else {
			continue
		}
		if query != "" {
			ui.jumpToFirstMatch(query)
		}
	}
}

func (ui *termUI) jumpToFirstMatch(query string) {
	for i, it := range ui.items {
		if it != nil && strings.Contains(strings.ToLower(it.Name), strings.ToLower(query)) {
			ui.cursor = i
			return
		}
	}
}
func (ui *termUI) jumpToMatch(query string, dir int) {
	if query == "" { return }
	for step := 1; step <= len(ui.items); step++ {
		idx := ui.cursor + dir*step
		if idx < 0 || idx >= len(ui.items) { return }
		it := ui.items[idx]
		if it != nil && strings.Contains(strings.ToLower(it.Name), strings.ToLower(query)) {
			ui.cursor = idx
			return
		}
	}
}

func (ui *termUI) doSpawnShell() {
	if ui.flags.NoSpawnShell { return }
	shell := os.Getenv("SHELL")
	if shell == "" { shell = "/bin/sh" }
	if ui.term != nil { ui.term.restore() }
	os.Stdout.WriteString("\x1b[?25h\x1b[?1049l")
	cmd := exec.Command(shell)
	cmd.Dir = ui.current.fullPath()
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	_ = cmd.Run()
	os.Stdout.WriteString("\x1b[?1049h\x1b[?25l")
	if st, err := makeRaw(int(os.Stdin.Fd())); err == nil {
		ui.term = st
	}
}
