package app

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strings"
)

type disksUI struct {
	flags   *Flags
	devices []device
	cursor  int
	sortAsc bool
	quitPath bool
	term    *termState
}

func newDisksUI(flags *Flags) *disksUI {
	devs := getDevices()
	sort.SliceStable(devs, func(i, j int) bool { return devs[i].Size > devs[j].Size })
	return &disksUI{flags: flags, devices: devs}
}

func (ui *disksUI) run() error {
	state, err := makeRaw(int(os.Stdin.Fd()))
	if err != nil {
		printDevices(os.Stdout, ui.flags)
		return nil
	}
	ui.term = state
	defer func() { if ui.term != nil { ui.term.restore() } }()
	out := os.Stdout
	out.WriteString("\x1b[?1049h\x1b[?25l")
	defer out.WriteString("\x1b[?25h\x1b[?1049l")
	if ui.flags.Mouse {
		out.WriteString("\x1b[?1000h\x1b[?1002h\x1b[?1006h")
		defer out.WriteString("\x1b[?1006l\x1b[?1002l\x1b[?1000l")
	}
	sb := newScreenBuf(out)
	input := bufio.NewReader(os.Stdin)
	for {
		sb.resize()
		ui.draw(sb)
		sb.flush()
		ev, err := readKey(input)
		if err != nil { break }
		if ev.special == "ctrlc" || ev.r == 'q' { break }
		if ev.r == 'Q' { ui.quitPath = true; break }
		switch {
		case ev.r == 'j' || ev.special == "down":
			if ui.cursor < len(ui.devices)-1 { ui.cursor++ }
		case ev.r == 'k' || ev.special == "up":
			if ui.cursor > 0 { ui.cursor-- }
		case ev.r == 'g':
			ui.cursor = 0
		case ev.r == 'G':
			if len(ui.devices) > 0 { ui.cursor = len(ui.devices)-1 }
		case ev.r == 's':
			ui.sortAsc = !ui.sortAsc
			sort.SliceStable(ui.devices, func(i, j int) bool {
				if ui.sortAsc { return ui.devices[i].Size < ui.devices[j].Size }
				return ui.devices[i].Size > ui.devices[j].Size
			})
		case ev.special == "enter" || ev.special == "right" || ev.r == 'l':
			if ui.cursor >= 0 && ui.cursor < len(ui.devices) {
				mp := ui.devices[ui.cursor].MountPoint
				// Scan the selected mount point interactively.
				scan := newScanner(ui.flags, nil, nil, nil, nil)
				root := scan.analyze(mp)
				// Restore terminal state handling is shared: run a nested
				// interactive UI would re-make raw; instead delegate by
				// returning a sentinel via quit handling is complex, so
				// do a minimal nested loop by reusing termUI with same term.
				inner := newTermUI(root, ui.flags, mp)
				inner.term = ui.term
				// Reuse run loop but without re-entering alt screen:
				// simplest is to draw using existing sb/input.
				ui.runInner(inner, sb, input)
				ui.term = inner.term
			}
		case ev.r == '?':
			tmp := &termUI{flags: ui.flags}
			if tmp.showHelp(sb, input) { return nil }
		}
	}
	if ui.quitPath {
		if ui.term != nil { ui.term.restore() }
		out.WriteString("\x1b[?25h\x1b[?1049l")
		if ui.cursor >= 0 && ui.cursor < len(ui.devices) {
			fmt.Fprintln(out, ui.devices[ui.cursor].MountPoint)
		}
	}
	return nil
}

func (ui *disksUI) runInner(inner *termUI, sb *screenBuf, input *bufio.Reader) {
	for {
		sb.resize()
		inner.draw(sb)
		sb.flush()
		ev, err := readKey(input)
		if err != nil { return }
		// q inside a device returns to the device list in the reference? It quits.
		if inner.handleKey(ev, sb, input) { return }
	}
}

func (ui *disksUI) draw(sb *screenBuf) {
	hs := style{fg: hexToColor(ui.flags.Style.Header.TextColor, 0), bg: hexToColor(ui.flags.Style.Header.BackgroundColor, 32)}
	if !ui.flags.Style.Header.Hidden {
		for x := 0; x < sb.w; x++ { sb.write(x, 0, " ", hs) }
		sb.write(0, 0, " gdu ~ Use arrow keys to navigate, press ? for help ", hs)
	}
	sb.write(0, 2, "Device name  Size      Used      Used part    Free      Mount point", style{bold: false})
	y := 3
	var totalUsed uint64
	for _, d := range ui.devices { totalUsed += d.Used }
	for i, d := range ui.devices {
		if y >= sb.h-1 { break }
		sizeStr := sizeTuple(int64(d.Size), ui.flags)
		usedStr := sizeTuple(int64(d.Used), ui.flags)
		freeStr := sizeTuple(int64(d.Free), ui.flags)
		bar := barString(int64(d.Used), int64(d.Size), !ui.flags.NoUnicode)
		line := fmt.Sprintf("%s %s %s %s▏ %s %s", d.Name, sizeStr, usedStr, prefixBarSpace(bar), freeStr, d.MountPoint)
		st := defaultStyle
		if i == ui.cursor {
			st = style{fg: 15, bg: 2, bold: true}
			line = line + strings.Repeat(" ", 8)
		}
		sb.write(0, y, line, st)
		y++
	}
	footerY := sb.h - 1
	fs := style{fg: hexToColor(ui.flags.Style.Footer.TextColor, 0), bg: hexToColor(ui.flags.Style.Footer.BackgroundColor, 32)}
	for x := 0; x < sb.w; x++ { sb.write(x, footerY, " ", fs) }
	order := "desc"
	if ui.sortAsc { order = "asc" }
	sb.write(0, footerY, fmt.Sprintf(" Total usage: %s Sorting by: size %s", sizeTuple(int64(totalUsed), ui.flags), order), fs)
}

func prefixBarSpace(bar string) string {
	// Device bars were shown with a leading space cell in captures.
	r := []rune(bar)
	if len(r) > 0 && r[0] != ' ' {
		return " " + bar
	}
	return bar
}

func sizeTuple(v int64, f *Flags) string {
	old := useColorOutput
	useColorOutput = false
	defer func() { useColorOutput = old }()
	ff := *f
	ff.NoPrefix = false
	ff.ShowInKiB = false
	s := formatSize(v, &ff)
	// Pad size part to 9 for columns after device? Caller assembles with spaces.
	// Captures: "/dev/nvme0n1 999.5 GiB 228.9 GiB ..." sizes are not padded
	// beyond a single space because device column dominates. Keep plain.
	return s
}
