	hs := style{fg: hexToColor(ui.flags.Style.Header.TextColor, 0), bg: hexToColor(ui.flags.Style.Header.BackgroundColor, 32)}
	if !ui.flags.Style.Header.Hidden {
		for x := 0; x < sb.w; x++ { sb.write(x, 0, " ", hs) }
		sb.write(0, 0, " gdu ~ Use arrow keys to navigate, press ? for help ", hs)
	}
	sb.write(0, 2, "Device name  Size      Used      Used part    Free      Mount point", style{bold: false})
	y := 3
	var totalUsed uint64
	for _, d := range ui.devices { totalUsed += d.Used }
	for i, d := range ui.devices {
		if y >= sb.h-1 { break }
		sizeStr := sizeTuple(int64(d.Size), ui.flags)
		usedStr := sizeTuple(int64(d.Used), ui.flags)
		freeStr := sizeTuple(int64(d.Free), ui.flags)
		bar := barString(int64(d.Used), int64(d.Size), !ui.flags.NoUnicode)
		line := fmt.Sprintf("%s %s %s %s▏ %s %s", d.Name, sizeStr, usedStr, prefixBarSpace(bar), freeStr, d.MountPoint)
		st := defaultStyle
		if i == ui.cursor {
			st = style{fg: 15, bg: 2, bold: true}
			line = line + strings.Repeat(" ", 8)
		}
		sb.write(0, y, line, st)
		y++
	}
	footerY := sb.h - 1
	fs := style{fg: hexToColor(ui.flags.Style.Footer.TextColor, 0), bg: hexToColor(ui.flags.Style.Footer.BackgroundColor, 32)}
	for x := 0; x < sb.w; x++ { sb.write(x, footerY, " ", fs) }
	order := "desc"
	if ui.sortAsc { order = "asc" }
	sb.write(0, footerY, fmt.Sprintf(" Total usage: %s Sorting by: size %s", sizeTuple(int64(totalUsed), ui.flags), order), fs)
}

func prefixBarSpace(bar string) string {
	// Device bars were shown with a leading space cell in captures.
	r := []rune(bar)
	if len(r) > 0 && r[0] != ' ' {
		return " " + bar
	}
	return bar
}

func sizeTuple(v int64, f *Flags) string {
	old := useColorOutput
	useColorOutput = false
	defer func() { useColorOutput = old }()
	ff := *f
	ff.NoPrefix = false
	ff.ShowInKiB = false
	s := formatSize(v, &ff)
	// Pad size part to 9 for columns after device? Caller assembles with spaces.
	// Captures: "/dev/nvme0n1 999.5 GiB 228.9 GiB ..." sizes are not padded
	// beyond a single space because device column dominates. Keep plain.
	return s
}
