		for i, j := 0, len(children)-1; i < j; i, j = i+1, j-1 {
			children[i], children[j] = children[j], children[i]
		}
	}
	ui.hasParentRow = ui.current.Parent != nil
	ui.items = nil
	if ui.hasParentRow {
		ui.items = append(ui.items, nil)
	}
