# normal row: after flag write, advance one extra space cell
s=s.replace('''		sb.write(x, y, flag, defaultStyle)
		x++''','''		sb.write(x, y, flag, defaultStyle)
		x++
		sb.write(x, y, " ", defaultStyle)
		x++''')
# word-aware footer writer: replace writeFooter closure
old='''	writeFooter := func(text string, st style) {
		sb.write(x, footerY, text, st)
		x += len([]rune(text))
	}'''
new='''	writeFooter := func(text string, st style) {
		// Word-aware clipping: a word that would overflow the
		// footer line is not drawn at all (and nothing after it).
		s := text
		for len(s) > 0 {
			if x >= sb.w {
				return
			}
			if s[0] == ' ' {
				sb.write(x, footerY, " ", st)
				x++
				s = s[1:]
				continue
			}
			end := len(s)
			for i, r := range s {
				if r == ' ' {
					end = i
					break
				}
			}
			word := s[:end]
			if x+len([]rune(word)) > sb.w {
				// Stop drawing the rest of this and following segments
				// by moving the cursor to the end.
				x = sb.w
				return
			}
			sb.write(x, footerY, word, st)
			x += len([]rune(word))
			s = s[end:]
		}
	}'''
