{"command":"cat > app/textedit.go <<'EOF'
package app

type textEdit struct {
	value  string
	cursor int // rune index
}

func (e *textEdit) runes() []rune { return []rune(e.value) }
func (e *textEdit) set(v string) {
	e.value = v
	e.cursor = len([]rune(v))
}

// handle processes an editing key. It returns (doneKey, changed, handled).
// doneKey is one of "enter", "tab", "esc", or "".
func (e *textEdit) handle(ev keyEvent) (string, bool, bool) {
	r := e.runes()
	switch ev.special {
	case "enter":
		return "enter", false, true
	case "tab":
		return "tab", false, true
	case "esc":
		return "esc", false, true
	case "backspace":
		if e.cursor > 0 {
			r = append(r[:e.cursor-1], r[e.cursor:]...)
			e.cursor--
			e.value = string(r)
			return "", true, true
		}
		return "", false, true
	case "delete":
		if e.cursor < len(r) {
			r = append(r[:e.cursor], r[e.cursor+1:]...)
			e.value = string(r)
			return "", true, true
		}
		return "", false, true
	case "left":
		if e.cursor > 0 { e.cursor-- }
		return "", false, true
	case "right":
		if e.cursor < len(r) { e.cursor++ }
		return "", false, true
	case "home":
		e.cursor = 0
		return "", false, true
	case "end":
		e.cursor = len(r)
		return "", false, true
	}
	switch ev.r {
	case 1: // Ctrl-A
		e.cursor = 0
		return "", false, true
	case 5: // Ctrl-E
		e.cursor = len(r)
		return "", false, true
	case 2: // Ctrl-B
		if e.cursor > 0 { e.cursor-- }
		return "", false, true
	case 6: // Ctrl-F
		if e.cursor < len(r) { e.cursor++ }
		return "", false, true
	case 11: // Ctrl-K
		if e.cursor < len(r) {
			e.value = string(r[:e.cursor])
			return "", true, true
		}
		return "", false, true
	case 21: // Ctrl-U
		e.value = ""
		e.cursor = 0
		return "", true, true
	case 23: // Ctrl-W: delete word before cursor
		if e.cursor == 0 { return "", false, true }
		start := e.cursor
		for start > 0 && r[start-1] == ' ' { start-- }
		for start > 0 && r[start-1] != ' ' { start-- }
		r = append(r[:start], r[e.cursor:]...)
		e.cursor = start
		e.value = string(r)
		return "", true, true
	}
	if ev.r >= 32 {
		r = append(r, 0)
		copy(r[e.cursor+1:], r[e.cursor:])
		r[e.cursor] = ev.r
		e.cursor++
		e.value = string(r)
		return "", true, true
	}
	return "", false, false
}

func (e *textEdit) visible(width int) string {
	r := e.runes()
	if len(r) <= width {
		return e.value
	}
	start := e.cursor - width
	if start < 0 { start = 0 }
	if start+width > len(r) { start = len(r) - width }
	return string(r[start : start+width])
}
EOF
