{"command":"python3 - <<'PY'
import pathlib
p=pathlib.Path("app/ui_modals.go"); s=p.read_text()
start=s.index("func (ui *termUI) viewFile")
end=s.index("func (ui *termUI) textInput")
new='''func (ui *termUI) viewFile(sb *screenBuf, input *bufio.Reader) bool {
	n := ui.currentNode()
	if n == nil || n.IsDir {
		return false
	}
	data, err := os.ReadFile(n.fullPath())
	content := ""
	if err != nil {
		content = err.Error()
	} else {
		content = string(data)
	}
	// The reference replaces the listing with a text view; the header
	// and footer of the parent listing remain visible.
	rawLines := strings.Split(strings.ReplaceAll(content, "\\r\\n", "\\n"), "\\n")
	offset := 0
	for {
		sb.resize()
		// Draw parent frame (header + footer), then replace the title and body.
		ui.draw(sb)
		// Title
		bg := defaultStyle
		for x := 0; x < sb.w; x++ {
			sb.write(x, 1, " ", bg)
		}
		sb.write(0, 1, fmt.Sprintf(" --- %s ---", n.fullPath()), style{fg: -1, bg: -1, bold: true})
		// Clear listing area
		listStart := 2
		listHeight := sb.h - listStart - 1
		lines := wrapViewLines(rawLines, sb.w)
		for y := listStart; y < listStart+listHeight; y++ {
			for x := 0; x < sb.w; x++ {
				sb.write(x, y, " ", bg)
			}
		}
		for i := 0; i < listHeight; i++ {
			idx := offset + i
			if idx >= len(lines) {
				break
			}
			sb.write(0, listStart+i, lines[idx], bg)
		}
		sb.flush()
		ev, err := readKey(input)
		if err != nil {
			return true
		}
		if ev.special == "ctrlc" {
			return false
		}
		if ev.r == 'q' || ev.r == 'Q' || ev.special == "esc" || ev.r == 'v' {
			return false
		}
		switch {
		case ev.r == 'j' || ev.special == "down":
			offset++
		case ev.r == 'k' || ev.special == "up":
			if offset > 0 {
				offset--
			}
		case ev.special == "pgdn":
			offset += listHeight
		case ev.special == "pgup":
			offset -= listHeight
		case ev.r == 'g':
			offset = 0
		case ev.r == 'G':
			offset = len(lines)
		}
		maxOff := len(lines) - listHeight
		if maxOff < 0 {
			maxOff = 0
		}
		if offset > maxOff {
			offset = maxOff
		}
		if offset < 0 {
			offset = 0
		}
	}
}

func wrapViewLines(raw []string, width int) []string {
	if width <= 0 {
		return raw
	}
	var out []string
	for _, line := range raw {
		line = strings.ReplaceAll(line, "\\t", "    ")
		r := []rune(line)
		if len(r) == 0 {
			out = append(out, "")
			continue
		}
		for len(r) > width {
			out = append(out, string(r[:width]))
			r = r[width:]
		}
		out = append(out, string(r))
	}
	return out
}

'''
s=s[:start]+new+s[end:]
p.write_text(s)
