func (ui *termUI) errorModal(sb *screenBuf, input *bufio.Reader, message string) bool {
	// Returns true if the application should quit.
	for {
		sb.resize()
		ui.draw(sb)
		w := 30
		lines := wrapModalText(message, w-2)
		h := len(lines) + 6
		x := (sb.w - w) / 2
		y := (sb.h - h) / 2
		if y < 0 {
			y = 0
		}
		ui.drawBox(sb, x, y, w, h, "", true)
		bg := style{fg: -1, bg: 0}
		for i, l := range lines {
			sb.write(x+1, y+2+i, padRight(l, w-2), bg)
		}
		optY := y + 2 + len(lines) + 1
		sb.write(x+1, optY, padRight("ok", w-2), style{fg: 15, bg: 2, bold: true})
		// Centre the ok label text itself: redraw spaces around via a centred write
		// (the pad above already filled; write label centred)
		ox := x + (w-2)/2
		sb.write(ox, optY, "ok", style{fg: 15, bg: 2, bold: true})
