			return true
		}
		if ev.special == "enter" || ev.special == "esc" {
			return false
		}
		if ev.special == "mouse" && !ev.mouseRelease && ev.mouseY == optY {
			return false
		}
	}
}

func wrapModalText(s string, width int) []string {
	// Split into breakable tokens (words and slash-terminated runs).
	type tok struct {
		text  string
		space bool // a space precedes this token
	}
	var toks []tok
	for _, word := range strings.Fields(s) {
		parts := []string{}
		cur := ""
		for _, r := range word {
			cur += string(r)
			if r == '/' {
				parts = append(parts, cur)
				cur = ""
			}
		}
		if cur != "" {
			parts = append(parts, cur)
		}
		for i, part := range parts {
			toks = append(toks, tok{text: part, space: i == 0 && len(toks) > 0})
		}
	}
	var lines []string
	cur := ""
	for _, t := range toks {
		add := t.text
		if t.space && cur != "" {
			add = " " + add
		}
		if cur != "" && len([]rune(cur))+len([]rune(add)) > width {
			lines = append(lines, cur)
			cur = t.text
			continue
		}
		cur += add
	}
	if cur != "" {
		lines = append(lines, cur)
	}
	for i, l := range lines {
		pad := (width - len([]rune(l))) / 2
		if pad > 0 {
			lines[i] = strings.Repeat(" ", pad) + l
		}
	}
	return lines
}

func (ui *termUI) exportFlow(sb *screenBuf, input *bufio.Reader) bool {
	edit := textEdit{}
	edit.set("export.json")
	focusButton := false
	for {
		sb.resize()
		ui.draw(sb)
		w, h := 50, 7
		x := (sb.w - w) / 2
		y := (sb.h - h) / 2
		if y < 0 {
			y = 0
		}
		ui.drawBox(sb, x, y, w, h, "Export data to JSON", true)
		bg := style{fg: -1, bg: 0}
		fieldY := y + 2
		sb.write(x+1, fieldY, " File name ", bg)
		fieldX := x + 1 + len(" File name ")
		fieldW := w - 2 - len(" File name ")
		fieldStyle := style{fg: 15, bg: 0}
		if !focusButton {
			fieldStyle = style{fg: 15, bg: 8}
		}
		sb.write(fieldX, fieldY, padRight(edit.visible(fieldW), fieldW), fieldStyle)
		btnStyle := bg
		if focusButton {
			btnStyle = style{fg: 15, bg: 2, bold: true}
		}
		btnY := y + 4
		btnX := x + (w-6)/2
		sb.write(btnX, btnY, "Export", btnStyle)
		sb.flush()

		ev, err := readKey(input)
		if err != nil {
			return true
		}
		if ev.special == "ctrlc" {
			return true
		}
		if !focusButton {
			done, _, handled := edit.handle(ev)
			if done == "enter" || done == "tab" {
				focusButton = true
				continue
			}
			if done == "esc" {
				return false
			}
			if handled {
				continue
			}
			continue
		}
		// Button focused.
		switch {
		case ev.special == "esc":
			return false
		case ev.special == "tab" || ev.special == "shift-tab":
			focusButton = false
			continue
		case ev.special == "enter":
			path := edit.value
			f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o600)
			if err != nil {
				return ui.errorModal(sb, input, fmt.Sprintf("Error creating file: %s", err))
			}
			err = exportAnalysis(f, ui.root, "")
			f.Close()
			if err != nil {
				return ui.errorModal(sb, input, fmt.Sprintf("Error creating file: %s", err))
			}
			return false
		case ev.special == "mouse" && !ev.mouseRelease && ev.mouseY == btnY:
			// treat as Enter by re-dispatching below via a synthetic enter
			path := edit.value
			f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o600)
			if err != nil {
				return ui.errorModal(sb, input, fmt.Sprintf("Error creating file: %s", err))
			}
			_ = exportAnalysis(f, ui.root, "")
			f.Close()
			return false
		}
	}
}

