package app

import (
	"os"
	"strings"
)

var terminalTrueColor = func() bool {
	ct := strings.ToLower(os.Getenv("COLORTERM"))
	if ct == "truecolor" || ct == "24bit" {
		return true
	}
	term := strings.ToLower(os.Getenv("TERM"))
	return strings.Contains(term, "truecolor") || strings.Contains(term, "24bit")
}()

func xtermPaletteRGB(i int) (int, int, int) {
	if i < 16 {
		base := [][3]int{
			{0, 0, 0}, {128, 0, 0}, {0, 128, 0}, {128, 128, 0},
			{0, 0, 128}, {128, 0, 128}, {0, 128, 128}, {192, 192, 192},
			{128, 128, 128}, {255, 0, 0}, {0, 255, 0}, {255, 255, 0},
			{0, 0, 255}, {255, 0, 255}, {0, 255, 255}, {255, 255, 255},
		}
		c := base[i]
		return c[0], c[1], c[2]
	}
	if i >= 232 {
		v := 8 + (i-232)*10
		return v, v, v
	}
	i -= 16
	levels := []int{0, 95, 135, 175, 215, 255}
	return levels[i/36], levels[(i/6)%6], levels[i%6]
}

func quantizeRGB(rgb int) int {
	// Exact theme colour whose reference rendering is known.
	if rgb == 0x3498db {
		return 32
	}
	r := (rgb >> 16) & 0xFF
	g := (rgb >> 8) & 0xFF
	b := rgb & 0xFF
	best := 0
	bestDist := 1 << 62
	for i := 0; i < 256; i++ {
		pr, pg, pb := xtermPaletteRGB(i)
		d := (r-pr)*(r-pr) + (g-pg)*(g-pg) + (b-pb)*(b-pb)
		if d < bestDist {
			bestDist = d
			best = i
		}
	}
	return best
}

func effectiveColor(c int) int {
	if c >= (1 << 24) {
		if terminalTrueColor {
			return c
		}
		return quantizeRGB(c & 0xFFFFFF)
	}
	return c
}
