type spinner struct {
	out      io.Writer
	done     chan struct{}
	finished chan struct{}
	frames   []rune
	text     string
	flags    *Flags
	mu       sync.Mutex
	count    int64
	size     int64
	width    int
}

func spinnerWidth() int {
	var ws winsize
	syscall.Syscall(syscall.SYS_IOCTL, os.Stdout.Fd(), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)))
	if ws.cols == 0 {
		return 100
	}
	return int(ws.cols)
}

func formatWithCommas(n int64) string {
	s := fmt.Sprintf("%d", n)
	if len(s) <= 3 {
		return s
	}
	var parts []string
	for len(s) > 3 {
		parts = append([]string{s[len(s)-3:]}, parts...)
		s = s[:len(s)-3]
	}
	parts = append([]string{s}, parts...)
	return strings.Join(parts, ",")
}

func startSpinner(out io.Writer, text string, flags *Flags) *spinner {
	s := &spinner{out: out, done: make(chan struct{}), finished: make(chan struct{}), text: text, flags: flags, frames: []rune("⠇⠏⠋⠙⠹⠸⠼⠴⠦⠧"), width: spinnerWidth()}
	s.erase()
	s.erase()
	idx := 0
	s.writeFrame(idx)
	idx++
	go func() {
		defer close(s.finished)
		ticker := time.NewTicker(100 * time.Millisecond)
		defer ticker.Stop()
		for {
			select {
			case <-s.done:
				return
			case <-ticker.C:
				s.erase()
				s.writeFrame(idx)
				idx++
			}
		}
	}()
	return s
}

func (s *spinner) erase() {
	fmt.Fprintf(s.out, "\\r%s\\r", strings.Repeat(" ", s.width))
}

func (s *spinner) writeFrame(idx int) {
	s.mu.Lock()
	count, size := s.count, s.size
	s.mu.Unlock()
	msg := s.text
	if count > 0 && !strings.HasPrefix(s.text, "Writing") {
		old := useColorOutput
		useColorOutput = false
		msg = fmt.Sprintf("Scanning... Total items: %s size: %s", formatWithCommas(count), formatSize(size, s.flags))
		useColorOutput = old
	}
	fmt.Fprintf(s.out, " %c %s", s.frames[idx%len(s.frames)], msg)
}

func (s *spinner) add(size int64) {
	s.mu.Lock()
	s.count++
	s.size += size
	s.mu.Unlock()
}

func (s *spinner) stop() {
	close(s.done)
	<-s.finished
	s.erase()
}
