func readNodeContent(n *Node) ([]byte, error) {
	// Find an archive ancestor, if any.
	var arch *Node
	for cur := n; cur != nil; cur = cur.Parent {
		if cur.Archive {
			arch = cur
			break
		}
	}
	if arch == nil {
		return os.ReadFile(n.fullPath())
	}
	// Build the zip entry name from node names below the archive.
	var parts []string
	for cur := n; cur != arch; cur = cur.Parent {
		parts = append([]string{cur.Name}, parts...)
	}
	entryName := strings.Join(parts, "/")
	reader, err := zip.OpenReader(arch.Path)
	if err != nil {
		return nil, err
	}
	defer reader.Close()
	for _, zf := range reader.File {
		if zf.Name == entryName {
			rc, err := zf.Open()
			if err != nil {
				return nil, err
			}
			defer rc.Close()
			return io.ReadAll(rc)
		}
	}
	return nil, os.ErrNotExist
}
