		"lightgreen": 0x90EE90,
	}
	lower := strings.ToLower(s)
	if lower == "default" || lower == "-" {
		return -1
	}
	if v, ok := namedRGB[lower]; ok {
		return (1 << 24) | v
	}
	if s == "" {
		return fallback
	}
	var v int
	if _, err := fmt.Sscanf(s, "%d", &v); err == nil {
		return v
	}
	return fallback
}

